def _write_gongfa_homemake_share_ui_markdown(
    path: Path,
    *,
    export_base: Path,
    flow_rows: list[dict[str, object]],
    edge_rows: list[dict[str, object]],
) -> None:
    by_topic = Counter(str(row.get("topic", "")) for row in flow_rows)
    lines = [
        "# GongFaHomeMake 聊天分享 UI 消费链路",
        "",
        f"- 导出目录：`{export_base}`",
        f"- 运行证据：{len(flow_rows)}；语义边：{len(edge_rows)}",
        f"- 运行主题：{', '.join(f'{name or '<empty>'}:{count}' for name, count in by_topic.most_common())}",
        "- 结论：发送侧有“详情页直接分享当前功法”和“通用分享选择面板”两条 UI 面。真实自创功法详情页分享走直接发送 `LING_JIE_GONGFA` 参数；接收侧由 `DecryptionHyper` 调用 `GetShareLingJieSkillInfo` 渲染富文本，并以 `createTime` 把完整 `GongFaHomeMakeShareVO` 缓存在 `_ChatLingJieSkillShareMap`。当前 Lua 文本资产里没有找到明确的 `GetChatShareLingJieSkillInfo(createTime)` 点击消费者，富文本 href 的最终点击处理可能在通用 UI/C# 层或未导出的绑定里。",
        "",
        "## 运行证据",
        "",
        "| step | topic | stage | source | file | line | code |",
        "| ---: | --- | --- | --- | --- | ---: | --- |",
    ]
    for row in flow_rows[:260]:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('step', ''), limit=20)} | "
            f"{_markdown_table_cell(row.get('topic', ''), limit=120)} | "
            f"{_markdown_table_cell(row.get('stage', ''), limit=150)} | "
            f"{_markdown_table_cell(row.get('source', ''), limit=100)} | "
            f"{_markdown_table_cell(row.get('file_name', ''), limit=160)} | "
            f"{_markdown_table_cell(row.get('line', ''), limit=40)} | "
            f"{_markdown_table_cell(row.get('code', ''), limit=420)} |"
        )
    lines.extend(["", "## 语义边", "", "| 源 | 关系 | 目标 | 证据 |", "| --- | --- | --- | --- |"])
    for row in edge_rows:
        source = f"{row.get('source_type', '')}:{row.get('source', '')}"
        target = f"{row.get('target_type', '')}:{row.get('target', '')}"
        lines.append(
            "| "
            f"{_markdown_table_cell(source, limit=320)} | "
            f"{_markdown_table_cell(row.get('edge', ''), limit=180)} | "
            f"{_markdown_table_cell(target, limit=320)} | "
            f"{_markdown_table_cell(row.get('evidence', ''), limit=440)} |"
        )
    lines.extend(
        [
            "",
            "## 边界",
            "",
            "- `ChatSharedItemContent` 支持 `ChatShareType.LingJieSkill` 的 UI 渲染，但 `ChatData._ChatShareItemDic` 当前未显式注册 LingJieSkill 的列表提供者；不要把它误判成详情页分享按钮的主路径。",
            "- `GetShareLingJieSkillInfo` 确认会缓存 `GongFaHomeMakeShareVO`，但点击富文本后如何取回该缓存，在当前 Lua 文本资产里尚未完全闭合。",
            "- 已闭合的接收链路是：chat params -> `DecryptionHyper` -> renderer -> `Chat_Share_16/17` markup + createTime cache。",
        ]
    )
    path.write_text("\n".join(lines), encoding="utf-8")


def build_fanxiu_gongfa_homemake_share_ui_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)
    flow_rows = _collect_gongfa_homemake_share_ui_flow(export_base)
    edge_rows = _collect_gongfa_homemake_share_ui_edges()
    flow_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_share_ui_flow.tsv",
        ["step", "topic", "stage", "source", "file_name", "function_name", "line", "code"],
        flow_rows,
    )
    edge_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_share_ui_edges.tsv",
        ["source_type", "source", "edge", "target_type", "target", "evidence"],
        edge_rows,
    )
    _write_gongfa_homemake_share_ui_markdown(
        output_dir / "hot_update_gongfa_homemake_share_ui_report.md",
        export_base=export_base,
        flow_rows=flow_rows,
        edge_rows=edge_rows,
    )
    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "counts": {
            "flow_rows": flow_count,
            "edge_rows": edge_count,
            "by_topic": dict(Counter(str(row.get("topic", "")) for row in flow_rows).most_common()),
        },
        "outputs": {
            "summary": str(output_dir / "hot_update_gongfa_homemake_share_ui_report.json"),
            "markdown": str(output_dir / "hot_update_gongfa_homemake_share_ui_report.md"),
            "flow": str(output_dir / "hot_update_gongfa_homemake_share_ui_flow.tsv"),
            "edges": str(output_dir / "hot_update_gongfa_homemake_share_ui_edges.tsv"),
        },
    }
    (output_dir / "hot_update_gongfa_homemake_share_ui_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def _collect_keyword_rows_from_paths(
    paths: Iterable[Path],
    categories: dict[str, list[str]],
    *,
    export_base: Path,
) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    unique_paths = sorted({path for path in paths if path.is_file()}, key=lambda item: str(item).lower())
    for path in unique_paths:
        try:
            lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
        except OSError:
            continue
        try:
            relative_path = str(path.relative_to(export_base))
        except ValueError:
            relative_path = path.name
        for line_no, line in enumerate(lines, start=1):
            compact = line.strip()
            if not compact:
                continue
            lower = compact.lower()
            for category, terms in categories.items():
                for term in terms:
                    if term.lower() in lower:
                        rows.append(
                            {
                                "category": category,
                                "file": path.name,
                                "relative_path": relative_path,
                                "line": line_no,
                                "signal": term,
                                "text": compact,
                                "path": str(path),
                            }
                        )
                        break
    rows.sort(key=lambda item: (str(item["category"]), str(item["relative_path"]), int(item["line"])))
    return rows


def _append_share_href_flow_rows(
    flow_rows: list[dict[str, object]],
    source: str,
    topic_by_stage: dict[str, str],
    rows: Iterable[dict[str, object]],
) -> None:
    for row in rows:
        category = str(row.get("category", ""))
        _append_homemake_flow_row(
            flow_rows,
            source=source,
            stage=category,
            topic=topic_by_stage.get(category, "support"),
            file_name=str(row.get("relative_path") or row.get("file") or ""),
            function_name="",
            line=row.get("line", ""),
            code=str(row.get("text", "")),
        )


def _collect_gongfa_homemake_share_href_flow(export_base: Path) -> list[dict[str, object]]:
    flow_rows: list[dict[str, object]] = []
    core_dir = _find_text_asset_dir(export_base, "lscripts", module="core")
    common_dir = _find_text_asset_dir(export_base, "lscripts", "gamesystem", module="common")
    chat_dir = _find_text_asset_dir(export_base, "lscripts", "gamesystem", "game", module="chat")

    lua_topic_by_stage = {
        "lua_text_ex_bridge": "lua_callback_registration",
        "lua_callback_mgr": "lua_callback_registration",
        "lua_global_href": "lua_href_dispatch",
        "lua_hyperlink_dispatch": "lingjie_href_consumer",
        "chat_render_cache": "chat_render_cache",
        "chat_label_gap": "chat_label_gap",
    }
    lua_categories = {
        "lua_text_ex_bridge": ["AddHyperClickEvent", "AddCallBackStringDelegate", "TextExBridge.AddHyperClickListener", "self.callid"],
        "lua_callback_mgr": ["_stringDelegateDic", "AddCallBackStringDelegate", "CallStringDelegate"],
        "lua_global_href": ["OnHyperLink", "DealWithHyperLinkStr"],
        "lua_hyperlink_dispatch": [
            "_HyperLinkCallDic",
            "HyperLinkType.LingJieSkill",
            "DealWithHyperLinkStr",
            "DealWithLingJieSkill",
            "GetChatShareLingJieSkillInfo",
            "OpenCreateSkillDetailView",
        ],
        "chat_render_cache": [
            "GetShareLingJieSkillInfo",
            "SaveChatShareLingJieSkillInfo",
            "GetChatShareLingJieSkillInfo",
            "Chat_Share_16",
            "Chat_Share_17",
            "66|",
            "Chat_Href_1",
        ],
        "chat_label_gap": ["labelContent", "AddHyperClickEvent", "AddLongPressEvent", "SetText", "chatHref", "lightChatHref", "OnChatContentLongPress"],
    }
    lua_paths: list[Path] = []
    if core_dir:
        lua_paths.extend(core_dir / name for name in ("LuaTextEx.lua", "LuaCallBackMgr.lua", "LuaGlobal.lua"))
    if common_dir:
        lua_paths.append(common_dir / "HyperLinkMgr.lua")
    if chat_dir:
        lua_paths.extend(chat_dir / name for name in ("ChatMgr.lua", "ChatData.lua", "ChatModel.lua", "ChatLabelChatCell.lua", "ChatType.lua"))
    _append_share_href_flow_rows(
        flow_rows,
        "lua_keyword",
        lua_topic_by_stage,
        _collect_keyword_rows_from_paths(lua_paths, lua_categories, export_base=export_base),
    )

    cpp_isil_root = export_base / "apk_static_index" / "cpp2il_2022_1_pre21_arm64_isil" / "IsilDump" / "Assembly-CSharp"
    cpp_cs_root = export_base / "apk_static_index" / "cpp2il_2022_1_pre21_arm64_diffable_cs" / "DiffableCs" / "Assembly-CSharp"
    cpp_topic_by_stage = {
        "cpp_text_ex_callback": "cpp_href_callback",
        "cpp_text_ex_bridge": "cpp_href_callback",
        "cpp_callback_manager": "cpp_href_callback",
        "cpp_href_info": "cpp_href_hit_test",
    }
    cpp_categories = {
        "cpp_text_ex_callback": [
            "clickHyperCallId",
            "OnPointerClick",
            "CallBackManager.CallStringDelegate",
            "CallStringDelegate",
            "m_HrefDic",
            "m_Content",
            "AddHyperClickListener",
        ],
        "cpp_text_ex_bridge": ["TextExBridge.AddHyperClickListener", "TextEx.AddHyperClickListener", "CheckNumberArray", "luaL_checknumber"],
        "cpp_callback_manager": ["CallStringDelegate", "CallStringDelegateList", "StringDelegate"],
        "cpp_href_info": ["HrefInfo", "CheckClick", "boxes", "m_Content", "m_Name"],
    }
    cpp_paths = [
        cpp_isil_root / "TextEx.txt",
        cpp_isil_root / "HrefInfo.txt",
        cpp_isil_root / "Core" / "Managers" / "CallBackManager.txt",
        cpp_isil_root / "LuaBridge" / "UIBridge" / "TextExBridge.txt",
        cpp_isil_root / "LuaBridge_UIBridge_TextExBridgeWrap.txt",
        cpp_cs_root / "TextEx.cs",
        cpp_cs_root / "HrefInfo.cs",
        cpp_cs_root / "Core" / "Managers" / "CallBackManager.cs",
        cpp_cs_root / "LuaBridge" / "UIBridge" / "TextExBridge.cs",
        cpp_cs_root / "LuaBridge_UIBridge_TextExBridgeWrap.cs",
    ]
    _append_share_href_flow_rows(
        flow_rows,
        "cpp2il_keyword",
        cpp_topic_by_stage,
        _collect_keyword_rows_from_paths(cpp_paths, cpp_categories, export_base=export_base),
    )

    topic_order = {
        "lua_callback_registration": 10,
        "cpp_href_callback": 20,
        "cpp_href_hit_test": 30,
        "lua_href_dispatch": 40,
        "lingjie_href_consumer": 50,
        "chat_render_cache": 60,
        "chat_label_gap": 70,
        "support": 90,
    }
    flow_rows.sort(
        key=lambda item: (
            topic_order.get(str(item["topic"]), 99),
            str(item["stage"]),
            str(item["file_name"]),
            int(item["line"]),
            str(item["code"]),
        )
    )
    for index, row in enumerate(flow_rows, start=1):
        row["step"] = index
    return flow_rows


