def _extract_localization_template(path: Path, key: str) -> str | None:
    try:
        lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
    except OSError:
        return None
    csv_prefix = f"{key},0,"
    lua_prefix = f"['{key}']="  # generated localization lua table
    for line in lines:
        compact = line.strip().rstrip(",")
        if compact.startswith(csv_prefix):
            return compact[len(csv_prefix) :].strip()
        if compact.startswith(lua_prefix):
            value = compact[len(lua_prefix) :].strip()
            if len(value) >= 2 and value[0] == "'" and value[-1] == "'":
                return value[1:-1]
            return value
    return None


def _collect_gongfa_homemake_detail_renderer_template_rows(export_base: Path) -> list[dict[str, object]]:
    paths = [
        path
        for path in _collect_gongfa_homemake_detail_renderer_paths(export_base)
        if path.name in {"localization.txt", "localization.lua"}
    ]
    rows: list[dict[str, object]] = []
    for key in GONGFA_HOMEMAKE_DETAIL_RENDERER_TEMPLATE_KEYS:
        found = False
        for path in sorted(paths, key=lambda item: (item.name != "localization.txt", str(item).lower())):
            template = _extract_localization_template(path, key)
            if template is None:
                continue
            try:
                relative_path = str(path.relative_to(export_base))
            except ValueError:
                relative_path = path.name
            rows.append(
                {
                    "key": key,
                    "template": template,
                    "source_file": path.name,
                    "relative_path": relative_path,
                    "path": str(path),
                }
            )
            found = True
            break
        if not found:
            rows.append({"key": key, "template": "", "source_file": "", "relative_path": "", "path": ""})
    return rows


def _parse_lua_key2index_fields(text: str) -> str:
    match = re.search(r"_key2index\s*=\s*\{([^}]*)\}", text, flags=re.S)
    if not match:
        return ""
    fields = []
    for name, index in re.findall(r"([A-Za-z_]\w*)\s*=\s*(\d+)", match.group(1)):
        fields.append((int(index), name))
    return ", ".join(name for _, name in sorted(fields))


def _collect_gongfa_homemake_detail_renderer_config_schema_rows(export_base: Path) -> list[dict[str, object]]:
    target_names = {
        "FeatureBase.lua",
        "MainFeature.lua",
        "MainFeaturePin.lua",
        "SideFeatureJie.lua",
        "SideFeaturePin.lua",
        "LingjieGongfaStar.lua",
        "LingjieGongfaJie.lua",
        "XianjieGongfaStar.lua",
        "Quality.lua",
    }
    notes = {
        "FeatureBase": "effectMap/xianEffectMap value id enters here; group links main feature, featureGroup links side/xian feature tables.",
        "MainFeature": "main feature group owns activation condition and broad describe metadata.",
        "MainFeaturePin": "main detail row display name/description/quality by gongfaId + pin.",
        "SideFeatureJie": "side feature rank row display name/description/param by featureGroup + jie.",
        "SideFeaturePin": "side feature pin row display name/description/quality by featureGroup + pin.",
        "LingjieGongfaStar": "base Gongfa star description and param source for GetMainDes.",
        "LingjieGongfaJie": "base Gongfa jie param source merged into star describe by GetMainDes.",
        "XianjieGongfaStar": "xian-effect main feature star/quality source by featureGroup + star.",
        "Quality": "color/color1 and UI frame color source for rich text and card frame rendering.",
    }
    rows: list[dict[str, object]] = []
    for path in sorted(_collect_gongfa_homemake_detail_renderer_paths(export_base), key=lambda item: str(item).lower()):
        if path.name not in target_names:
            continue
        try:
            text = path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        try:
            relative_path = str(path.relative_to(export_base))
        except ValueError:
            relative_path = path.name
        table_name = path.stem
        rows.append(
            {
                "table_name": table_name,
                "fields": _parse_lua_key2index_fields(text),
                "relative_path": relative_path,
                "semantic_note": notes.get(table_name, ""),
                "path": str(path),
            }
        )
    return rows


