def _typed_pool_runtime_reconstruction_rows(schema_rows: list[dict[str, str]]) -> list[dict[str, object]]:
    field_notes = []
    for row in schema_rows:
        packet = str(row.get("packet", "")).strip()
        field = str(row.get("field", "")).strip()
        read_method = str(row.get("read_method", "")).strip()
        nested_type = str(row.get("nested_type", "")).strip()
        if packet in {"SM_FightResult", "SM_FightResultFunnel", "FightResultVO"} and field:
            label = f"{packet}.{field}:{read_method}"
            if nested_type:
                label += f"->{nested_type}"
            field_notes.append(label)
    return [
        {
            "step": 1,
            "operation": "Split typed pools into one message segment",
            "input_pool": "poolTypeDataLength",
            "result": "For each message, consume the next counts for int, float, string, uint, sn, and double pools.",
            "applies_to": "all socket messages",
        },
        {
            "step": 2,
            "operation": "Read packet identity",
            "input_pool": "int pool",
            "result": "The first int in the current segment is proId; keep only 60005/60041/60054/60055 for this probe family.",
            "applies_to": "SM_FightResult family",
        },
        {
            "step": 3,
            "operation": "Read packet serial number when present",
            "input_pool": "sn pool",
            "result": "Keep only a redacted/truncated sn for correlation; it is not gameplay semantics.",
            "applies_to": "all retained messages",
        },
        {
            "step": 4,
            "operation": "Replay BaseMessage primitive readers",
            "input_pool": "int,uint,float,double,string pools",
            "result": "readInt/readShort/readByte/readBool consume int; readLong consumes two uints; readDouble consumes double; readString consumes string.",
            "applies_to": "generated Lua packet classes",
        },
        {
            "step": 5,
            "operation": "Decode message lists",
            "input_pool": "int pool plus nested typed values",
            "result": "readMessageList2List reads length, optional next length when len<-1, a shared-proId flag byte, then one shared proId or per-item proIds.",
            "applies_to": "SM_FightResult.results -> FightResultVO",
        },
        {
            "step": 6,
            "operation": "Apply packet-family field order",
            "input_pool": "schema rows",
            "result": "; ".join(field_notes[:30]),
            "applies_to": "SM_FightResult/SM_FightResultFunnel/FightResultVO",
        },
        {
            "step": 7,
            "operation": "Validate against display consumer",
            "input_pool": "decoded message object",
            "result": "Compare reconstructed results with SkillBase.SetSM_FightResult/HurtData display path, especially damageView, recoverHp, fightEffect, and delayTime.",
            "applies_to": "static decode quality check",
        },
    ]


