def _load_socket_capture_frames(path: Path) -> tuple[list[dict[str, object]], str]:
    try:
        data = json.loads(path.read_text(encoding="utf-8", errors="ignore"))
    except (OSError, json.JSONDecodeError) as exc:
        return [], f"{type(exc).__name__}: {exc}"
    raw_frames = data.get("frames", []) if isinstance(data, dict) else []
    if not isinstance(raw_frames, list):
        return [], "frames field is not a list"
    return [frame for frame in raw_frames if isinstance(frame, dict)], ""


def build_fanxiu_socket_result_sample_coverage_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    """Report whether existing decoded TCP fixtures contain combat-result packet samples."""
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)
    decoded_paths = _find_socket_capture_decoded_jsons(export_base)
    targets = _socket_result_sample_target_specs()
    target_ids = {int(row["pro_id"]) for row in targets}
    target_by_id = {int(row["pro_id"]): row for row in targets}

    all_frames: list[dict[str, object]] = []
    fixture_rows: list[dict[str, object]] = []
    hit_rows: list[dict[str, object]] = []
    errors: list[str] = []
    for decoded_path in decoded_paths:
        frames, error = _load_socket_capture_frames(decoded_path)
        if error:
            errors.append(f"{decoded_path.name}: {error}")
        target_frames = [frame for frame in frames if isinstance(frame.get("pro_id"), int) and frame.get("pro_id") in target_ids]
        all_frames.extend({**frame, "_fixture": decoded_path.name} for frame in frames)
        fixture_rows.append(
            {
                "fixture": decoded_path.name,
                "path": str(decoded_path),
                "frame_count": len(frames),
                "c2s_frames": sum(1 for frame in frames if frame.get("direction") == "c2s"),
                "s2c_frames": sum(1 for frame in frames if frame.get("direction") == "s2c"),
                "parsed_frames": sum(1 for frame in frames if frame.get("parsed")),
                "target_result_frames": len(target_frames),
                "target_ids_present": _unique_join(
                    str(frame.get("pro_id", "")) for frame in target_frames if isinstance(frame.get("pro_id"), int)
                ),
                "error": error,
            }
        )
        for index, frame in enumerate(frames):
            pro_id = frame.get("pro_id")
            if not isinstance(pro_id, int) or pro_id not in target_ids:
                continue
            spec = target_by_id[pro_id]
            hit_rows.append(
                {
                    "fixture": decoded_path.name,
                    "index": index,
                    "direction": frame.get("direction", ""),
                    "offset": frame.get("offset", ""),
                    "pro_id": pro_id,
                    "packet": spec["packet"],
                    "family": spec["family"],
                    "name": frame.get("name", ""),
                    "frame_len": frame.get("frame_len", ""),
                    "payload_len": frame.get("payload_len", ""),
                    "zlib": frame.get("zlib", ""),
                    "parsed": bool(frame.get("parsed")),
                    "remain": frame.get("remain", ""),
                    "privacy_note": "metadata_only_no_payload_values",
                }
            )

    aggregate_counts: Counter[int] = Counter()
    aggregate_parsed_counts: Counter[int] = Counter()
    aggregate_files: dict[int, set[str]] = {int(row["pro_id"]): set() for row in targets}
    aggregate_offsets: dict[int, list[str]] = {int(row["pro_id"]): [] for row in targets}
    protocol_counts: Counter[tuple[str, int, str]] = Counter()
    for frame in all_frames:
        pro_id = frame.get("pro_id")
        if not isinstance(pro_id, int):
            continue
        direction = str(frame.get("direction", ""))
        name = str(frame.get("name", ""))
        protocol_counts[(direction, pro_id, name)] += 1
        if pro_id in target_ids:
            aggregate_counts[pro_id] += 1
            if frame.get("parsed"):
                aggregate_parsed_counts[pro_id] += 1
            aggregate_files.setdefault(pro_id, set()).add(str(frame.get("_fixture", "")))
            if len(aggregate_offsets.setdefault(pro_id, [])) < 8:
                aggregate_offsets[pro_id].append(str(frame.get("offset", "")))

    target_rows: list[dict[str, object]] = []
    for spec in targets:
        pro_id = int(spec["pro_id"])
        count = aggregate_counts.get(pro_id, 0)
        target_rows.append(
            {
                "pro_id": pro_id,
                "packet": spec["packet"],
                "family": spec["family"],
                "expected_direction": spec["expected_direction"],
                "sample_use": spec["sample_use"],
                "frame_count": count,
                "parsed_count": aggregate_parsed_counts.get(pro_id, 0),
                "fixtures": _unique_join(sorted(aggregate_files.get(pro_id, set()))),
                "first_offsets": _unique_join(aggregate_offsets.get(pro_id, [])),
                "coverage_status": "present" if count else "absent",
                "interpretation": "usable existing sample candidate" if count else "no existing decoded sample for this packet id",
            }
        )
    protocol_rows = [
        {
            "direction": direction,
            "pro_id": pro_id,
            "name": name,
            "count": count,
            "is_target_result_packet": pro_id in target_ids,
        }
        for (direction, pro_id, name), count in sorted(
            protocol_counts.items(), key=lambda item: (-item[1], item[0][0], item[0][1], item[0][2])
        )
    ]

    target_count = _write_tsv(
        output_dir / "hot_update_socket_result_sample_coverage_targets.tsv",
        [
            "pro_id",
            "packet",
            "family",
            "expected_direction",
            "sample_use",
            "frame_count",
            "parsed_count",
            "fixtures",
            "first_offsets",
            "coverage_status",
            "interpretation",
        ],
        target_rows,
    )
    fixture_count = _write_tsv(
        output_dir / "hot_update_socket_result_sample_coverage_fixtures.tsv",
        [
            "fixture",
            "path",
            "frame_count",
            "c2s_frames",
            "s2c_frames",
            "parsed_frames",
            "target_result_frames",
            "target_ids_present",
            "error",
        ],
        fixture_rows,
    )
    protocol_count = _write_tsv(
        output_dir / "hot_update_socket_result_sample_coverage_protocol_counts.tsv",
        ["direction", "pro_id", "name", "count", "is_target_result_packet"],
        protocol_rows,
    )
    hit_count = _write_tsv(
        output_dir / "hot_update_socket_result_sample_coverage_hits.tsv",
        [
            "fixture",
            "index",
            "direction",
            "offset",
            "pro_id",
            "packet",
            "family",
            "name",
            "frame_len",
            "payload_len",
            "zlib",
            "parsed",
            "remain",
            "privacy_note",
        ],
        hit_rows,
    )

    ordinary_buff_count = aggregate_counts.get(60034, 0)
    fight_family_count = sum(aggregate_counts.get(pro_id, 0) for pro_id in [60005, 60041, 60054, 60055])
    verdict = {
        "decoded_fixtures_found": bool(decoded_paths),
        "target_coverage_written": target_count == len(targets),
        "ordinary_buff_result_sample_present": ordinary_buff_count > 0,
        "fight_result_family_sample_present": fight_family_count > 0,
        "existing_captures_cover_result_attribution": ordinary_buff_count > 0 or fight_family_count > 0,
        "safe_to_skip_existing_fixtures_for_result_attribution": ordinary_buff_count == 0 and fight_family_count == 0,
        "metadata_only_no_payload_values_exported": True,
    }
    verdict["supports_result_sample_coverage_report"] = (
        verdict["decoded_fixtures_found"] and verdict["target_coverage_written"] and verdict["metadata_only_no_payload_values_exported"]
    )

    lines = [
        "# Socket Result Sample Coverage Probe",
        "",
        f"- Export root: `{export_base}`",
        f"- Decoded fixtures scanned: {len(decoded_paths)}",
        f"- Target rows: {target_count}",
        f"- Fixture rows: {fixture_count}",
        f"- Protocol count rows: {protocol_count}",
        f"- Target hit rows: {hit_count}",
        "- Scope: scans existing decoded TCP fixture metadata for combat-result packet ids. It does not read live traffic, hook the client, or export parsed payload values.",
    ]
    if errors:
        lines.extend(["", "## Fixture Errors", ""])
        lines.extend(f"- `{_markdown_table_cell(error, limit=240)}`" for error in errors[:12])
    lines.extend(
        [
            "",
            "## Target Coverage",
            "",
            "| ProId | Packet | Family | Frames | Parsed | Status |",
            "| ---: | --- | --- | ---: | ---: | --- |",
        ]
    )
    for row in target_rows:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('pro_id', ''), limit=20)} | "
            f"{_markdown_table_cell(row.get('packet', ''), limit=120)} | "
            f"{_markdown_table_cell(row.get('family', ''), limit=80)} | "
            f"{_markdown_table_cell(row.get('frame_count', ''), limit=20)} | "
            f"{_markdown_table_cell(row.get('parsed_count', ''), limit=20)} | "
            f"{_markdown_table_cell(row.get('coverage_status', ''), limit=40)} |"
        )
    lines.extend(
        [
            "",
            "## Interpretation",
            "",
            f"- Ordinary buff result samples (`60034`) present: `{ordinary_buff_count}`.",
            f"- FightResult-family samples (`60005/60041/60054/60055`) present: `{fight_family_count}`.",
            "- If both are zero, existing decoded captures are useful for socket framing/codec validation only, not for combat-result attribution.",
        ]
    )
    markdown_path = output_dir / "hot_update_socket_result_sample_coverage_report.md"
    markdown_path.write_text("\n".join(lines), encoding="utf-8")

    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "counts": {
            "decoded_fixtures": len(decoded_paths),
            "total_frames": len(all_frames),
            "target_rows": target_count,
            "fixture_rows": fixture_count,
            "protocol_count_rows": protocol_count,
            "target_hit_rows": hit_count,
            "ordinary_buff_result_frames": ordinary_buff_count,
            "fight_result_family_frames": fight_family_count,
        },
        "verdict": verdict,
        "outputs": {
            "targets": str(output_dir / "hot_update_socket_result_sample_coverage_targets.tsv"),
            "fixtures": str(output_dir / "hot_update_socket_result_sample_coverage_fixtures.tsv"),
            "protocol_counts": str(output_dir / "hot_update_socket_result_sample_coverage_protocol_counts.tsv"),
            "hits": str(output_dir / "hot_update_socket_result_sample_coverage_hits.tsv"),
            "markdown": str(markdown_path),
            "json": str(output_dir / "hot_update_socket_result_sample_coverage_report.json"),
        },
    }
    (output_dir / "hot_update_socket_result_sample_coverage_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def _read_text_or_empty(path: Path) -> str:
    if not path.is_file():
        return ""
    try:
        return path.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return ""


def _read_json_dict_or_empty(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8", errors="ignore"))
    except (OSError, json.JSONDecodeError):
        return {}
    return data if isinstance(data, dict) else {}


def build_fanxiu_combat_formula_authority_contrast_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    """Summarize which combat-like flows expose local formulas vs server result authority."""
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)

    blld_formula_rows = _read_tsv_rows(output_dir / "hot_update_blld_combat_formula_evidence.tsv")
    blld_report = _read_text_or_empty(output_dir / "hot_update_blld_combat_mechanics_report.md")
    blld_authority_rows = _read_tsv_rows(output_dir / "hot_update_blld_authority_operations.tsv")
    finish_row = next((row for row in blld_authority_rows if row.get("operation") == "FinishAndReward"), {})

    result_producer_checks = _read_tsv_rows(
        output_dir / "hot_update_gongfa_homemake_mechanism_result_producer_checks.tsv"
    )
    result_producer_report = _read_text_or_empty(
        output_dir / "hot_update_gongfa_homemake_mechanism_result_producer_report.md"
    )
    result_check_by_name = {row.get("check", ""): row for row in result_producer_checks}

    timeline_formula_rows = _read_tsv_rows(output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_formula_terms.tsv")
    timeline_report = _read_text_or_empty(output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_report.md")

    capture_json = _read_json_dict_or_empty(output_dir / "hot_update_socket_capture_fixture_codec_calibration_report.json")
    capture_counts = capture_json.get("counts", {}) if isinstance(capture_json.get("counts"), dict) else {}

    blld_local_formula_found = bool(blld_formula_rows) or "BLLDFightComponent:AddDamageResult" in blld_report
    gongfa_result_producer_absent = (
        result_check_by_name.get("client_pool_create_sm_fight_result", {}).get("status") == "not_found"
        and result_check_by_name.get("client_send_sm_fight_result", {}).get("status") == "not_found"
        and result_check_by_name.get("client_new_fight_result_vo", {}).get("status") == "not_found"
    ) or "未找到 `GetMessageFromPools(_SM_FightResult" in result_producer_report
    timeline_projection_only = (
        len(timeline_formula_rows) == 0
        and "not numeric formula authority" in timeline_report
        or "not_formula_authority" in timeline_report
    )
    socket_fixture_calibrated = bool(capture_counts) and int(capture_counts.get("mismatched_frame_body_lengths", -1)) == 0
    socket_fixture_lacks_fight_result = int(capture_counts.get("fight_result_family_frames", 0) or 0) == 0

    contrast_rows = [
        {
            "flow": "BLLD local mini-game combat",
            "formula_or_result_layer": "local formula visible",
            "evidence": f"{len(blld_formula_rows)} formula evidence rows; BLLDFightComponent:AddDamageResult report hit={ 'yes' if 'BLLDFightComponent:AddDamageResult' in blld_report else 'no' }",
            "wire_authority": finish_row.get("authority_class", "unknown"),
            "boundary_note": finish_row.get(
                "local_preview_note",
                "Local small-game formula exists, but final reward/state still needs server packets.",
            ),
            "confidence": "high" if blld_local_formula_found else "missing_input",
        },
        {
            "flow": "GongFaHomeMake / main fight result family",
            "formula_or_result_layer": "server result packet consumer",
            "evidence": "client SM_FightResult producer checks are not_found; SkillBase consumes SM_FightResult/Funnel results",
            "wire_authority": "server_to_client_SM_FightResult_family",
            "boundary_note": "Client consumes FightResultVO values and projects them to skills; visible Lua/Cpp2IL does not construct/send SM_FightResult.",
            "confidence": "high" if gongfa_result_producer_absent else "needs_review",
        },
        {
            "flow": "Timeline q_hurt_events / HurtData projection",
            "formula_or_result_layer": "display projection",
            "evidence": f"{len(timeline_formula_rows)} formula-authority rows in focused excerpt",
            "wire_authority": "downstream_of_server_result",
            "boundary_note": "Timeline supplies hit time/percent/track; it splits already-computed FightResultVO values, not the source formula.",
            "confidence": "high" if timeline_projection_only else "needs_review",
        },
        {
            "flow": "Existing TCP decoded fixture",
            "formula_or_result_layer": "socket framing calibration",
            "evidence": (
                f"{capture_counts.get('matched_frame_body_lengths', 0)}/{capture_counts.get('frame_rows', 0)} "
                "frames match candidate compressed-int body-length model"
            ),
            "wire_authority": "metadata_only_no_payload_export",
            "boundary_note": "Fixture calibrates framing/codec; it has no FightResult-family frames, so it cannot prove combat result semantics.",
            "confidence": "high" if socket_fixture_calibrated else "missing_input",
        },
    ]
    evidence_rows = [
        {
            "source": "hot_update_blld_combat_formula_evidence.tsv",
            "signal": "blld_formula_rows",
            "value": len(blld_formula_rows),
            "interpretation": "BLLD exposes a local small-game combat formula surface.",
        },
        {
            "source": "hot_update_blld_authority_operations.tsv",
            "signal": "FinishAndReward_authority_class",
            "value": finish_row.get("authority_class", ""),
            "interpretation": "BLLD can submit a local battle summary while server packets still return final rewards/state.",
        },
        {
            "source": "hot_update_gongfa_homemake_mechanism_result_producer_checks.tsv",
            "signal": "client_sm_fight_result_producer_absent",
            "value": gongfa_result_producer_absent,
            "interpretation": "Main GongFa/Funnel fight result values are visible as server result consumption, not client production.",
        },
        {
            "source": "hot_update_gongfa_homemake_timeline_hurt_projection_formula_terms.tsv",
            "signal": "timeline_formula_authority_rows",
            "value": len(timeline_formula_rows),
            "interpretation": "Timeline hit metadata is a projection layer when no formula-authority terms are present.",
        },
        {
            "source": "hot_update_socket_capture_fixture_codec_calibration_report.json",
            "signal": "fight_result_family_frames",
            "value": capture_counts.get("fight_result_family_frames", ""),
            "interpretation": "The current decoded capture fixture cannot calibrate FightResult semantics if this is zero.",
        },
    ]

    contrast_count = _write_tsv(
        output_dir / "hot_update_combat_formula_authority_contrast.tsv",
        ["flow", "formula_or_result_layer", "evidence", "wire_authority", "boundary_note", "confidence"],
        contrast_rows,
    )
    evidence_count = _write_tsv(
        output_dir / "hot_update_combat_formula_authority_evidence.tsv",
        ["source", "signal", "value", "interpretation"],
        evidence_rows,
    )

    verdict = {
        "blld_local_formula_found": blld_local_formula_found,
        "gongfa_result_client_producer_absent": gongfa_result_producer_absent,
        "timeline_hurt_is_projection_not_formula_authority": timeline_projection_only,
        "socket_fixture_codec_calibrated": socket_fixture_calibrated,
        "socket_fixture_lacks_fight_result_family": socket_fixture_lacks_fight_result,
    }
    verdict["supports_combat_formula_authority_contrast"] = all(
        verdict[key]
        for key in [
            "blld_local_formula_found",
            "gongfa_result_client_producer_absent",
            "timeline_hurt_is_projection_not_formula_authority",
            "socket_fixture_codec_calibrated",
        ]
    )

    lines = [
        "# Combat Formula Authority Contrast Probe",
        "",
        f"- Export root: `{export_base}`",
        f"- Contrast rows: {contrast_count}",
        f"- Evidence rows: {evidence_count}",
        "- Scope: compare already-derived evidence so local mini-game formulas are not confused with main fight result authority.",
        "",
        "## Contrast",
        "",
        "| Flow | Layer | Evidence | Wire authority | Boundary | Confidence |",
        "| --- | --- | --- | --- | --- | --- |",
    ]
    for row in contrast_rows:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('flow', ''), limit=120)} | "
            f"{_markdown_table_cell(row.get('formula_or_result_layer', ''), limit=120)} | "
            f"{_markdown_table_cell(row.get('evidence', ''), limit=180)} | "
            f"{_markdown_table_cell(row.get('wire_authority', ''), limit=120)} | "
            f"{_markdown_table_cell(row.get('boundary_note', ''), limit=260)} | "
            f"{_markdown_table_cell(row.get('confidence', ''), limit=80)} |"
        )
    lines.extend(
        [
            "",
            "## Reading",
            "",
            "- `BLLD` is a real local formula surface for a local mini-game/combat-like mode.",
            "- GongFaHomeMake/main fight evidence still points to server-produced `SM_FightResult*` values and client-side projection.",
            "- Timeline hit files can affect timing, tracks and percent split; they do not currently expose the numeric source formula.",
            "- The current decoded TCP fixture validates the socket codec but lacks FightResult-family samples.",
        ]
    )
    markdown_path = output_dir / "hot_update_combat_formula_authority_contrast_report.md"
    markdown_path.write_text("\n".join(lines), encoding="utf-8")

    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "counts": {
            "contrast_rows": contrast_count,
            "evidence_rows": evidence_count,
            "blld_formula_rows": len(blld_formula_rows),
            "timeline_formula_authority_rows": len(timeline_formula_rows),
            "fight_result_family_frames": int(capture_counts.get("fight_result_family_frames", 0) or 0),
        },
        "verdict": verdict,
        "outputs": {
            "contrast": str(output_dir / "hot_update_combat_formula_authority_contrast.tsv"),
            "evidence": str(output_dir / "hot_update_combat_formula_authority_evidence.tsv"),
            "markdown": str(markdown_path),
            "json": str(output_dir / "hot_update_combat_formula_authority_contrast_report.json"),
        },
    }
    (output_dir / "hot_update_combat_formula_authority_contrast_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def _cpp2il_main_combat_role_specs(export_base: Path) -> list[dict[str, object]]:
    cs_root = (
        export_base
        / "apk_static_index"
        / "cpp2il_2022_1_pre21_arm64_diffable_cs"
        / "DiffableCs"
        / "Assembly-CSharp"
    )
    return [
        {
            "role": "battle_state_manager",
            "path": cs_root / "Core" / "Battle" / "BattleMgr.cs",
            "expected_terms": ["V_InBattle", "V_PresentationSpeed", "isPause"],
            "interpretation": "BattleMgr exposes battle/pause/presentation-speed state, not visible damage formula ownership.",
        },
        {
            "role": "skill_target_geometry_bridge",
            "path": cs_root / "LuaBridge" / "Skill" / "SkillCastBridge.cs",
            "expected_terms": ["CircleCastAll", "LineCastAll", "RectangleCastAll", "SectorCastAll"],
            "interpretation": "SkillCastBridge is target-selection geometry and range debug surface.",
        },
        {
            "role": "timeline_hurt_config_schema",
            "path": cs_root / "SkillBaseConfig.cs",
            "expected_terms": ["q_hurt_events", "q_keyframe_events", "q_track_time"],
            "interpretation": "SkillBaseConfig stores timeline hurt/keyframe metadata used for projection timing.",
        },
        {
            "role": "timeline_hurt_track",
            "path": cs_root / "Skill" / "HurtEventTrack.cs",
            "expected_terms": ["TrackClipType", "RefreshClipCount", "UpdateDuration"],
            "interpretation": "HurtEventTrack is timeline/editor/playback track metadata, not numeric authority.",
        },
        {
            "role": "timeline_hurt_data_export",
            "path": cs_root / "HurtEventData.cs",
            "expected_terms": ["AddHurtEventTrackClip", "AddPlayableConfigInfo", "SetHurtEventTrack"],
            "interpretation": "HurtEventData converts timeline clip config into stored hit-event metadata.",
        },
        {
            "role": "timeline_hurt_curve_container",
            "path": cs_root / "HurtScriptTable.cs",
            "expected_terms": ["CurveList"],
            "interpretation": "HurtScriptTable is a container for timeline curve config.",
        },
    ]


def _cpp2il_main_combat_role_rows(export_base: Path) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    for spec in _cpp2il_main_combat_role_specs(export_base):
        path = Path(spec["path"])
        text = _read_text_or_empty(path)
        expected_terms = [str(term) for term in spec.get("expected_terms", [])]
        found_terms = [term for term in expected_terms if term in text]
        strong_formula_terms = [
            "finalDamage",
            "AddDamageResult",
            "CalculateDamage",
            "CalcDamage",
            "FightResultVO",
            "SM_FightResult",
            "xianEffectMap",
            "XianjieGongfaStar",
            "BuffResource",
            "GongFaHomeMake",
        ]
        formula_hits = [term for term in strong_formula_terms if term in text]
        rows.append(
            {
                "role": spec["role"],
                "source_file": str(path),
                "file_exists": path.is_file(),
                "expected_terms_found": " | ".join(found_terms),
                "expected_term_count": len(found_terms),
                "strong_formula_terms_found": " | ".join(formula_hits),
                "strong_formula_term_count": len(formula_hits),
                "interpretation": spec["interpretation"],
            }
        )
    return rows


def _cpp2il_main_combat_formula_hit_rows(export_base: Path) -> list[dict[str, object]]:
    roots = [
        export_base / "apk_static_index" / "cpp2il_2022_1_pre21_arm64_diffable_cs" / "DiffableCs" / "Assembly-CSharp",
        export_base / "apk_static_index" / "cpp2il_2022_1_pre21_arm64_isil" / "IsilDump" / "Assembly-CSharp",
    ]
    strong_terms = [
        "finalDamage",
        "AddDamageResult",
        "CalculateDamage",
        "CalcDamage",
        "FightResultVO",
        "SM_FightResult",
        "damageView",
        "recoverHp",
        "ShowSkillDamageRangeDebug",
        "xianEffectMap",
        "XianjieGongfaStar",
        "BuffResource",
        "GongFaHomeMake",
    ]
    rows: list[dict[str, object]] = []
    for root in roots:
        if not root.is_dir():
            continue
        suffixes = {".cs", ".txt"}
        for path in root.rglob("*"):
            if not path.is_file() or path.suffix.lower() not in suffixes:
                continue
            rel = str(path.relative_to(root)).replace("\\", "/")
            if rel.startswith(("mscorlib/", "System", "Unity", "UWA", "ShartZipLib")):
                continue
            text = _read_text_or_empty(path)
            if not text:
                continue
            for line_no, line in enumerate(text.splitlines(), start=1):
                found = [term for term in strong_terms if term in line]
                if not found:
                    continue
                rows.append(
                    {
                        "source_root": str(root),
                        "source_file": str(path),
                        "relative_file": rel,
                        "line": line_no,
                        "terms": " | ".join(found),
                        "line_text": line.strip(),
                    }
                )
    return rows


def build_fanxiu_cpp2il_main_combat_formula_surface_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    """Scan Cpp2IL main combat-adjacent surfaces for local formula evidence."""
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)
    role_rows = _cpp2il_main_combat_role_rows(export_base)
    formula_rows = _cpp2il_main_combat_formula_hit_rows(export_base)

    role_count = _write_tsv(
        output_dir / "hot_update_cpp2il_main_combat_formula_surface_roles.tsv",
        [
            "role",
            "source_file",
            "file_exists",
            "expected_terms_found",
            "expected_term_count",
            "strong_formula_terms_found",
            "strong_formula_term_count",
            "interpretation",
        ],
        role_rows,
    )
    formula_count = _write_tsv(
        output_dir / "hot_update_cpp2il_main_combat_formula_surface_hits.tsv",
        ["source_root", "source_file", "relative_file", "line", "terms", "line_text"],
        formula_rows,
    )

    found_role_names = {str(row.get("role", "")) for row in role_rows if row.get("expected_term_count")}
    strong_formula_hits_outside_known_geometry = [
        row
        for row in formula_rows
        if "ShowSkillDamageRangeDebug" not in str(row.get("line_text", ""))
        and "SkillCastBridge" not in str(row.get("relative_file", ""))
    ]
    verdict = {
        "battle_state_surface_found": "battle_state_manager" in found_role_names,
        "skillcast_geometry_surface_found": "skill_target_geometry_bridge" in found_role_names,
        "timeline_hurt_metadata_surface_found": bool(
            {"timeline_hurt_config_schema", "timeline_hurt_track", "timeline_hurt_data_export"} & found_role_names
        ),
        "strong_main_combat_formula_hits_found": bool(strong_formula_hits_outside_known_geometry),
    }
    verdict["supports_cpp2il_main_combat_formula_surface_boundary"] = (
        verdict["battle_state_surface_found"]
        and verdict["skillcast_geometry_surface_found"]
        and verdict["timeline_hurt_metadata_surface_found"]
        and not verdict["strong_main_combat_formula_hits_found"]
    )

    lines = [
        "# Cpp2IL Main Combat Formula Surface Probe",
        "",
        f"- Export root: `{export_base}`",
        f"- Role rows: {role_count}",
        f"- Strong formula hit rows: {formula_count}",
        "- Scope: Cpp2IL diffable C# and ISIL surfaces around battle, skill target selection, and hurt timeline metadata.",
        "",
        "## Role Surfaces",
        "",
        "| Role | Exists | Terms | Formula terms | Interpretation |",
        "| --- | --- | --- | --- | --- |",
    ]
    for row in role_rows:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('role', ''), limit=100)} | "
            f"{_markdown_table_cell(row.get('file_exists', ''), limit=20)} | "
            f"{_markdown_table_cell(row.get('expected_terms_found', ''), limit=160)} | "
            f"{_markdown_table_cell(row.get('strong_formula_terms_found', ''), limit=160)} | "
            f"{_markdown_table_cell(row.get('interpretation', ''), limit=260)} |"
        )
    lines.extend(
        [
            "",
            "## Conclusion",
            "",
            "- Cpp2IL exposes battle state, target-selection geometry, and timeline hurt metadata surfaces.",
            "- It does not expose a strong main-combat local formula surface in the scanned Cpp2IL diffable/ISIL outputs.",
            "- This agrees with the Lua packet/consumer evidence: main combat numbers are still best treated as server result values projected by the client.",
        ]
    )
    markdown_path = output_dir / "hot_update_cpp2il_main_combat_formula_surface_report.md"
    markdown_path.write_text("\n".join(lines), encoding="utf-8")

    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "counts": {
            "role_rows": role_count,
            "formula_hit_rows": formula_count,
            "strong_hits_outside_known_geometry": len(strong_formula_hits_outside_known_geometry),
        },
        "verdict": verdict,
        "outputs": {
            "roles": str(output_dir / "hot_update_cpp2il_main_combat_formula_surface_roles.tsv"),
            "hits": str(output_dir / "hot_update_cpp2il_main_combat_formula_surface_hits.tsv"),
            "markdown": str(markdown_path),
            "json": str(output_dir / "hot_update_cpp2il_main_combat_formula_surface_report.json"),
        },
    }
    (output_dir / "hot_update_cpp2il_main_combat_formula_surface_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def _find_fanxiu_lua_text_asset(export_base: Path, file_name: str) -> Path | None:
    root = export_base / "by_source" / "lscripts"
    if not root.is_dir():
        return None
    candidates = [path for path in root.rglob(file_name) if path.is_file()]
    if not candidates:
        return None
    candidates.sort(key=lambda path: (0 if "generate" in str(path).lower() else 1, len(str(path)), str(path).lower()))
    return candidates[0]


def _parse_lua_python_string(value: str) -> str:
    try:
        parsed = ast.literal_eval(value)
    except (SyntaxError, ValueError):
        return value.strip("'\"")
    return str(parsed)


def _parse_xianjie_gongfa_star_lua(path: Path | None) -> list[dict[str, object]]:
    if not path or not path.is_file():
        return []
    try:
        text = path.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return []
    desc_block_match = re.search(r"local\s+_A\s*=\s*\{(?P<body>.*?)\n\}\s*\nlocal\s+_B", text, flags=re.S)
    param_block_match = re.search(r"local\s+_B\s*=\s*\{(?P<body>.*?)\n\}\s*\nlocal\s+_C", text, flags=re.S)
    desc_block = desc_block_match.group("body") if desc_block_match else text
    param_block = param_block_match.group("body") if param_block_match else text
    desc_by_index = {
        int(match.group(1)): _parse_lua_python_string(match.group(2))
        for match in re.finditer(r"\[(\d+)\]\s*=\s*('(?:\\.|[^'])*')\s*,", desc_block, flags=re.S)
    }
    param_by_index: dict[int, list[object]] = {}
    for match in re.finditer(r"\[(\d+)\]\s*=\s*\{([^{}]*)\}\s*,", param_block):
        raw_items = [item.strip() for item in match.group(2).split(",") if item.strip()]
        values: list[object] = []
        numeric_only = True
        for item in raw_items:
            if not re.fullmatch(r"-?\d+(?:\.\d+)?", item):
                numeric_only = False
                break
            values.append(float(item) if "." in item else int(item))
        if numeric_only:
            param_by_index[int(match.group(1))] = values

    rows: list[dict[str, object]] = []
    for line_no, line in enumerate(text.splitlines(), start=1):
        if "setmetatable({" not in line or "[2]=" not in line or "[3]=" not in line:
            continue
        row_body = line.split("setmetatable({", 1)[1]
        fields = {
            int(field): raw.strip()
            for field, raw in re.findall(r"\[(\d+)\]\s*=\s*([^,\}]+)", row_body)
        }

        def int_field(index: int) -> int | None:
            raw = fields.get(index, "")
            return int(raw) if re.fullmatch(r"-?\d+", raw) else None

        desc_ref = fields.get(6, "")
        param_ref = fields.get(7, "")
        desc_index_match = re.fullmatch(r"_A\[(\d+)\]", desc_ref)
        param_index_match = re.fullmatch(r"_B\[(\d+)\]", param_ref)
        desc_index = int(desc_index_match.group(1)) if desc_index_match else None
        param_index = int(param_index_match.group(1)) if param_index_match else None
        rows.append(
            {
                "source_file": str(path),
                "line": line_no,
                "id": int_field(1),
                "featureGroup": int_field(2),
                "star": int_field(3),
                "feature": int_field(4),
                "quality": int_field(5),
                "describe_index": desc_index or "",
                "param_index": param_index or "",
                "describe": desc_by_index.get(desc_index or -1, ""),
                "param": param_by_index.get(param_index or -1, []),
                "sortValue": int_field(8),
                "raw": line.strip(),
            }
        )
    return rows


def _infer_xianjie_formula_slots(template: str, combined_params: list[object]) -> list[dict[str, object]]:
    fragments = [fragment for fragment in re.split(r"(?<!%)%s", template)]
    rows: list[dict[str, object]] = []
    for index, value in enumerate(combined_params[: max(0, len(fragments) - 1)], start=1):
        before = strip_fanxiu_rich_text(fragments[index - 1])[-80:]
        after = strip_fanxiu_rich_text(fragments[index])[:80] if index < len(fragments) else ""
        hint_text = f"{before}{{value}}{after}"
        if "共附加" in before or "共可附加" in before:
            meaning = "base_extra_spirit_damage_percent"
        elif "造成" in before or "伤害" in after:
            meaning = "funnel_or_extra_spirit_damage_percent"
        elif "招架" in after or "招架" in before:
            meaning = "spirit_parry_reduction_percent"
        else:
            meaning = "display_placeholder"
        rows.append(
            {
                "slot": index,
                "value": value,
                "meaning_guess": meaning,
                "context": hint_text,
            }
        )
    return rows


def build_fanxiu_gongfa_homemake_mechanism_formula_surface_probe(
    *,
    buff_id: str | int = "386001010",
    star: int = 1,
    jie: int = 1,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    """Recover the client-visible XianShu formula text surface for a selected mechanism."""
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)
    buff_id_text = str(buff_id or "").strip() or "386001010"
    buff_prefix = buff_id_text[:-1] if len(buff_id_text) >= 2 else buff_id_text
    star = max(1, int(star))
    jie = max(1, int(jie))

    side_rows = _load_gongfa_renderer_parsed_rows(export_base, "SideFeatureJie")
    buff_rows = _load_gongfa_renderer_parsed_rows(export_base, "BuffResource")
    target_side = next(
        (
            row
            for row in side_rows
            if str(row.get("feature", "")).strip() == buff_prefix
            or buff_id_text.startswith(str(row.get("feature", "")).strip())
        ),
        None,
    )
    target_buff = next((row for row in buff_rows if str(row.get("id", "")).strip() == buff_id_text), None)
    feature_group = _renderer_int((target_side or {}).get("featureGroup"))
    xianjie_path = _find_fanxiu_lua_text_asset(export_base, "XianjieGongfaStar.lua")
    star_rows = _parse_xianjie_gongfa_star_lua(xianjie_path)
    family_rows = [
        row
        for row in star_rows
        if feature_group is not None and _renderer_int(row.get("featureGroup")) == feature_group
    ]
    selected_star = next(
        (row for row in family_rows if _renderer_int(row.get("star")) == star),
        family_rows[0] if family_rows else None,
    )
    star_params = list((selected_star or {}).get("param") or [])
    side_params = list((target_side or {}).get("param") or [])
    combined_params = _table_add_table(star_params, side_params)
    template = str((selected_star or {}).get("describe") or "")
    rendered_rich = _lua_percent_format(template, *combined_params)
    rendered_plain = strip_fanxiu_rich_text(rendered_rich)
    formula_slot_rows = _infer_xianjie_formula_slots(template, combined_params)

    surface_rows = [
        {
            "buff_id": buff_id_text,
            "buff_name": (target_buff or {}).get("name_plain") or (target_buff or {}).get("name") or "",
            "side_feature_id": (target_side or {}).get("id", ""),
            "side_feature_name": (target_side or {}).get("name_plain") or (target_side or {}).get("name") or "",
            "feature_group": feature_group or "",
            "jie": (target_side or {}).get("jie", jie),
            "star": (selected_star or {}).get("star", star),
            "xianjie_star_id": (selected_star or {}).get("id", ""),
            "star_feature": (selected_star or {}).get("feature", ""),
            "star_params": json.dumps(star_params, ensure_ascii=False),
            "side_feature_params": json.dumps(side_params, ensure_ascii=False),
            "combined_params": json.dumps(combined_params, ensure_ascii=False),
            "placeholder_count": len(re.findall(r"(?<!%)%s", template)),
            "rendered_plain": rendered_plain,
            "source_file": (selected_star or {}).get("source_file", str(xianjie_path or "")),
            "source_line": (selected_star or {}).get("line", ""),
        }
    ]
    family_out_rows = []
    for row in family_rows[:80]:
        row_params = list(row.get("param") or [])
        row_combined = _table_add_table(row_params, side_params)
        family_out_rows.append(
            {
                "feature_group": row.get("featureGroup", ""),
                "star": row.get("star", ""),
                "xianjie_star_id": row.get("id", ""),
                "star_feature": row.get("feature", ""),
                "star_params": json.dumps(row_params, ensure_ascii=False),
                "side_feature_params": json.dumps(side_params, ensure_ascii=False),
                "combined_params": json.dumps(row_combined, ensure_ascii=False),
                "rendered_plain": strip_fanxiu_rich_text(_lua_percent_format(str(row.get("describe") or ""), *row_combined)),
                "source_line": row.get("line", ""),
            }
        )
    formula_out_rows = [
        {
            "buff_id": buff_id_text,
            "slot": row.get("slot", ""),
            "value": row.get("value", ""),
            "meaning_guess": row.get("meaning_guess", ""),
            "context": row.get("context", ""),
        }
        for row in formula_slot_rows
    ]

    surface_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_mechanism_formula_surface.tsv",
        [
            "buff_id",
            "buff_name",
            "side_feature_id",
            "side_feature_name",
            "feature_group",
            "jie",
            "star",
            "xianjie_star_id",
            "star_feature",
            "star_params",
            "side_feature_params",
            "combined_params",
            "placeholder_count",
            "rendered_plain",
            "source_file",
            "source_line",
        ],
        surface_rows,
    )
    family_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_mechanism_formula_family.tsv",
        [
            "feature_group",
            "star",
            "xianjie_star_id",
            "star_feature",
            "star_params",
            "side_feature_params",
            "combined_params",
            "rendered_plain",
            "source_line",
        ],
        family_out_rows,
    )
    slot_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_mechanism_formula_slots.tsv",
        ["buff_id", "slot", "value", "meaning_guess", "context"],
        formula_out_rows,
    )

    lines = [
        "# GongFaHomeMake 单机制公式展示面探针",
        "",
        f"- 导出目录：`{export_base}`",
        f"- 目标 buff：`{buff_id_text}`",
        f"- 目标 star/jie：`{star}/{jie}`",
        "- 口径：还原客户端可见的 `XianjieGongfaStar.describe` 模板和 `SideFeatureJie.param` 合成文案，不把它当服务端运行时公式。",
        "",
        "## 结论",
        "",
        f"- `SideFeatureJie.feature` 通过前缀关联到 `{buff_id_text}`，featureGroup=`{feature_group or ''}`。",
        f"- `XianjieGongfaStar` 选中 star=`{(selected_star or {}).get('star', '')}` 的模板，star 参数为 `{star_params}`。",
        f"- `SideFeatureJie.param` 为 `{side_params}`，与 star 参数逐位相加后为 `{combined_params}`。",
        "- 这能解释游戏详情里展示的百分比文案；服务端实际伤害仍以 `SM_FightResultFunnel.results` 回包为准。",
        "",
        "## 占位值",
        "",
        "| Slot | Value | Guess | Context |",
        "| --- | --- | --- | --- |",
    ]
    for row in formula_slot_rows:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('slot', ''), limit=20)} | "
            f"{_markdown_table_cell(row.get('value', ''), limit=40)} | "
            f"{_markdown_table_cell(row.get('meaning_guess', ''), limit=80)} | "
            f"{_markdown_table_cell(row.get('context', ''), limit=180)} |"
        )
    lines.extend(["", "## 渲染结果", "", "```text", rendered_plain, "```", ""])
    markdown_path = output_dir / "hot_update_gongfa_homemake_mechanism_formula_surface_report.md"
    markdown_path.write_text("\n".join(lines), encoding="utf-8")

    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "params": {"buff_id": buff_id_text, "star": star, "jie": jie},
        "counts": {
            "surface_rows": surface_count,
            "family_rows": family_count,
            "slot_rows": slot_count,
            "xianjie_star_rows": len(star_rows),
            "family_star_rows": len(family_rows),
        },
        "verdict": {
            "client_visible_formula_template_found": bool(template),
            "side_feature_params_found": bool(side_params),
            "star_params_found": bool(star_params),
            "side_feature_params_fill_template": bool(template) and len(combined_params) >= len(re.findall(r"(?<!%)%s", template)),
            "formula_is_display_surface_not_runtime_authority": True,
            "runtime_formula_found": False,
        },
        "outputs": {
            "surface": str(output_dir / "hot_update_gongfa_homemake_mechanism_formula_surface.tsv"),
            "family": str(output_dir / "hot_update_gongfa_homemake_mechanism_formula_family.tsv"),
            "slots": str(output_dir / "hot_update_gongfa_homemake_mechanism_formula_slots.tsv"),
            "markdown": str(markdown_path),
            "json": str(output_dir / "hot_update_gongfa_homemake_mechanism_formula_surface_report.json"),
        },
    }
    (output_dir / "hot_update_gongfa_homemake_mechanism_formula_surface_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def build_fanxiu_gongfa_homemake_xianshu_formula_catalog_probe(
    *,
    star: int = 1,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    """Build a display-formula catalog for all readable XianShu side features."""
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)
    star = max(1, int(star))

    side_rows = _load_gongfa_renderer_parsed_rows(export_base, "SideFeatureJie")
    buff_rows = _load_gongfa_renderer_parsed_rows(export_base, "BuffResource")
    buff_by_prefix: dict[str, list[dict[str, Any]]] = {}
    for buff in buff_rows:
        buff_id = str(buff.get("id") or "").strip()
        if len(buff_id) >= 2:
            buff_by_prefix.setdefault(buff_id[:-1], []).append(buff)

    xianjie_path = _find_fanxiu_lua_text_asset(export_base, "XianjieGongfaStar.lua")
    star_rows = _parse_xianjie_gongfa_star_lua(xianjie_path)
    star_by_group: dict[int, list[dict[str, object]]] = {}
    for row in star_rows:
        feature_group = _renderer_int(row.get("featureGroup"))
        if feature_group is not None:
            star_by_group.setdefault(feature_group, []).append(row)
    for rows in star_by_group.values():
        rows.sort(key=lambda row: (_renderer_int(row.get("star")) or 999999, _renderer_int(row.get("id")) or 999999))

    catalog_rows: list[dict[str, object]] = []
    for side in side_rows:
        feature_group = _renderer_int(side.get("featureGroup"))
        if feature_group is None or feature_group not in star_by_group:
            continue
        selected_star = next(
            (row for row in star_by_group[feature_group] if _renderer_int(row.get("star")) == star),
            star_by_group[feature_group][0],
        )
        side_feature = str(side.get("feature") or "").strip()
        side_params = list(side.get("param") or [])
        star_params = list(selected_star.get("param") or [])
        combined_params = _table_add_table(star_params, side_params)
        template = str(selected_star.get("describe") or "")
        rendered_plain = strip_fanxiu_rich_text(_lua_percent_format(template, *combined_params))
        candidate_buffs = buff_by_prefix.get(side_feature, [])
        catalog_rows.append(
            {
                "side_feature_id": side.get("id", ""),
                "side_feature_name": side.get("name_plain") or side.get("name") or "",
                "feature_group": feature_group,
                "jie": side.get("jie", ""),
                "side_feature": side_feature,
                "star": selected_star.get("star", star),
                "xianjie_star_id": selected_star.get("id", ""),
                "star_feature": selected_star.get("feature", ""),
                "buff_ids": _unique_join([buff.get("id", "") for buff in candidate_buffs], limit=8),
                "buff_names": _unique_join([buff.get("name_plain") or buff.get("name") or "" for buff in candidate_buffs], limit=8),
                "star_params": json.dumps(star_params, ensure_ascii=False),
                "side_feature_params": json.dumps(side_params, ensure_ascii=False),
                "combined_params": json.dumps(combined_params, ensure_ascii=False),
                "placeholder_count": len(re.findall(r"(?<!%)%s", template)),
                "rendered_plain": rendered_plain,
                "source_file": selected_star.get("source_file", str(xianjie_path or "")),
                "source_line": selected_star.get("line", ""),
            }
        )
    catalog_rows.sort(
        key=lambda row: (
            _renderer_int(row.get("feature_group")) or 0,
            _renderer_int(row.get("jie")) or 0,
            _renderer_int(row.get("side_feature_id")) or 0,
        )
    )

    group_acc: dict[int, dict[str, object]] = {}
    for row in catalog_rows:
        feature_group = _renderer_int(row.get("feature_group")) or 0
        group = group_acc.setdefault(
            feature_group,
            {
                "feature_group": feature_group,
                "rows": 0,
                "side_feature_names": [],
                "buff_names": [],
                "star_rows": len(star_by_group.get(feature_group, [])),
                "sample_rendered_plain": row.get("rendered_plain", ""),
            },
        )
        group["rows"] = int(group["rows"]) + 1
        if row.get("side_feature_name"):
            group["side_feature_names"].append(str(row.get("side_feature_name")))
        if row.get("buff_names"):
            group["buff_names"].append(str(row.get("buff_names")))
    group_rows = [
        {
            "feature_group": group["feature_group"],
            "rows": group["rows"],
            "star_rows": group["star_rows"],
            "side_feature_names": _unique_join(group["side_feature_names"], limit=8),
            "buff_names": _unique_join(group["buff_names"], limit=8),
            "sample_rendered_plain": group["sample_rendered_plain"],
        }
        for group in sorted(group_acc.values(), key=lambda item: int(item["feature_group"]))
    ]

    catalog_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_xianshu_formula_catalog.tsv",
        [
            "side_feature_id",
            "side_feature_name",
            "feature_group",
            "jie",
            "side_feature",
            "star",
            "xianjie_star_id",
            "star_feature",
            "buff_ids",
            "buff_names",
            "star_params",
            "side_feature_params",
            "combined_params",
            "placeholder_count",
            "rendered_plain",
            "source_file",
            "source_line",
        ],
        catalog_rows,
    )
    group_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_xianshu_formula_groups.tsv",
        ["feature_group", "rows", "star_rows", "side_feature_names", "buff_names", "sample_rendered_plain"],
        group_rows,
    )

    lines = [
        "# GongFaHomeMake 仙书公式展示目录",
        "",
        f"- 导出目录：`{export_base}`",
        f"- 使用 star：`{star}`",
        f"- 目录行：{catalog_count}",
        f"- featureGroup：{group_count}",
        "- 口径：这是 `XianjieGongfaStar.describe + SideFeatureJie.param` 的客户端展示公式目录，不是服务端运行时公式。",
        "",
        "## 样例",
        "",
        "| FeatureGroup | Side Feature | Buff | Params | Text |",
        "| --- | --- | --- | --- | --- |",
    ]
    for row in catalog_rows[:12]:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('feature_group', ''), limit=40)} | "
            f"{_markdown_table_cell(row.get('side_feature_name', ''), limit=80)} | "
            f"{_markdown_table_cell(row.get('buff_names', ''), limit=80)} | "
            f"{_markdown_table_cell(row.get('combined_params', ''), limit=80)} | "
            f"{_markdown_table_cell(row.get('rendered_plain', ''), limit=220)} |"
        )
    markdown_path = output_dir / "hot_update_gongfa_homemake_xianshu_formula_catalog_report.md"
    markdown_path.write_text("\n".join(lines), encoding="utf-8")

    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "params": {"star": star},
        "counts": {
            "catalog_rows": catalog_count,
            "group_rows": group_count,
            "xianjie_star_rows": len(star_rows),
            "xianjie_feature_groups": len(star_by_group),
            "rows_with_buff_candidates": sum(1 for row in catalog_rows if row.get("buff_ids")),
        },
        "verdict": {
            "xianshu_formula_catalog_available": catalog_count > 0,
            "buff_candidates_partially_linked": any(row.get("buff_ids") for row in catalog_rows),
            "formula_is_display_surface_not_runtime_authority": True,
            "runtime_formula_found": False,
        },
        "outputs": {
            "catalog": str(output_dir / "hot_update_gongfa_homemake_xianshu_formula_catalog.tsv"),
            "groups": str(output_dir / "hot_update_gongfa_homemake_xianshu_formula_groups.tsv"),
            "markdown": str(markdown_path),
            "json": str(output_dir / "hot_update_gongfa_homemake_xianshu_formula_catalog_report.json"),
        },
    }
    (output_dir / "hot_update_gongfa_homemake_xianshu_formula_catalog_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def _build_xianshu_feature_group_gongfa_index(export_base: Path) -> dict[str, dict[str, object]]:
    tables = {
        "gongfa": _load_gongfa_renderer_parsed_rows(export_base, "Gongfa"),
        "main_feature": _load_gongfa_renderer_parsed_rows(export_base, "MainFeature"),
        "feature_base": _load_gongfa_renderer_parsed_rows(export_base, "FeatureBase"),
        "side_jie": _load_gongfa_renderer_parsed_rows(export_base, "SideFeatureJie"),
    }
    side_groups = {
        _renderer_int(row.get("featureGroup"))
        for row in tables["side_jie"]
        if _renderer_int(row.get("featureGroup")) is not None
    }
    index: dict[str, dict[str, object]] = {}
    for gongfa in tables["gongfa"]:
        gongfa_id = _renderer_int(gongfa.get("id"))
        if gongfa_id is None or _renderer_int(gongfa.get("scopeType")) != 2:
            continue
        main_features = [
            row for row in tables["main_feature"] if _renderer_int(row.get("gongfaId")) == gongfa_id
        ]
        main_groups = {
            _renderer_int(value)
            for main_feature in main_features
            for value in (main_feature.get("groups") if isinstance(main_feature.get("groups"), list) else [])
            if _renderer_int(value) is not None
        }
        feature_groups = {
            _renderer_int(row.get("featureGroup"))
            for row in tables["feature_base"]
            if (
                _renderer_int(row.get("keyFeature")) == gongfa_id
                or _renderer_int(row.get("group")) in main_groups
            )
            and _renderer_int(row.get("featureGroup")) in side_groups
        }
        for feature_group in feature_groups:
            if feature_group is None:
                continue
            key = str(feature_group)
            item = index.setdefault(key, {"gongfa_ids": [], "gongfa_names": []})
            item["gongfa_ids"].append(str(gongfa_id))
            name = str(gongfa.get("name_plain") or gongfa.get("name") or "")
            if name:
                item["gongfa_names"].append(name)
    for item in index.values():
        item["gongfa_ids"] = _unique_join(item.get("gongfa_ids", []), limit=12, sep="、")
        item["gongfa_names"] = _unique_join(item.get("gongfa_names", []), limit=12, sep="、")
    return index


def get_fanxiu_gongfa_homemake_xianshu_formula_catalog(
    *,
    gongfa_id: str | int | None = None,
    query: str = "",
    limit: int = 80,
    star: int = 1,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    catalog_path = output_dir / "hot_update_gongfa_homemake_xianshu_formula_catalog.tsv"
    groups_path = output_dir / "hot_update_gongfa_homemake_xianshu_formula_groups.tsv"
    if not catalog_path.is_file() or not groups_path.is_file():
        build_fanxiu_gongfa_homemake_xianshu_formula_catalog_probe(star=star, export_root=export_base)

    rows = _read_tsv_rows(catalog_path)
    groups = _read_tsv_rows(groups_path)
    group_index = _build_xianshu_feature_group_gongfa_index(export_base)
    query_text = str(query or "").strip().lower()
    gongfa_id_text = str(gongfa_id or "").strip()

    enriched_rows: list[dict[str, str]] = []
    for row in rows:
        feature_group = str(row.get("feature_group", "")).strip()
        group_meta = group_index.get(feature_group, {})
        item = {
            **row,
            "gongfa_ids": str(group_meta.get("gongfa_ids", "")),
            "gongfa_names": str(group_meta.get("gongfa_names", "")),
        }
        if gongfa_id_text:
            gongfa_ids = set(_split_gongfa_homemake_list_cell(item.get("gongfa_ids", "")))
            if gongfa_id_text not in gongfa_ids:
                continue
        if query_text:
            haystack = " ".join(
                str(item.get(field, ""))
                for field in (
                    "side_feature_name",
                    "feature_group",
                    "side_feature",
                    "buff_ids",
                    "buff_names",
                    "gongfa_ids",
                    "gongfa_names",
                    "combined_params",
                    "rendered_plain",
                )
            ).lower()
            if query_text not in haystack:
                continue
        enriched_rows.append(item)

    limited_items = enriched_rows[: max(1, min(int(limit), 200))]
    matched_groups = {str(row.get("feature_group", "")).strip() for row in enriched_rows}
    group_rows = []
    for group in groups:
        feature_group = str(group.get("feature_group", "")).strip()
        if feature_group not in matched_groups:
            continue
        group_meta = group_index.get(feature_group, {})
        group_rows.append(
            {
                **group,
                "gongfa_ids": str(group_meta.get("gongfa_ids", "")),
                "gongfa_names": str(group_meta.get("gongfa_names", "")),
            }
        )

    return {
        "export_root": str(export_base),
        "source": "hot_update_gongfa_homemake_xianshu_formula_catalog",
        "params": {
            "gongfa_id": gongfa_id_text,
            "query": query,
            "limit": limit,
            "star": star,
        },
        "total": len(enriched_rows),
        "items": limited_items,
        "groups": group_rows[: max(1, min(int(limit), 200))],
        "counts": {
            "rows": len(enriched_rows),
            "feature_groups": len(matched_groups),
            "rows_with_buff_candidates": sum(1 for row in enriched_rows if str(row.get("buff_ids", "")).strip()),
        },
        "outputs": {
            "catalog": str(catalog_path),
            "groups": str(groups_path),
        },
    }


def _classify_xianshu_formula_usage(path: Path, term: str, line: str) -> tuple[str, str]:
    path_text = path.as_posix().lower()
    file_name = path.name
    if term == "LingjieGongfa_XianjieGongfaStar":
        if "getconfigtable" in line.lower():
            return "config_cache_load", "GongfahomemakeData loads the generated XianjieGongfaStar config table."
        if "uninstallconfigtable" in line.lower():
            return "config_cache_uninstall", "GongfahomemakeData releases the generated config table after caching by featureGroup/star."
        return "config_name_reference", "Reference to the generated XianjieGongfaStar config name."
    if term == "GetXianjieGongfaStarCfgEx":
        if file_name == "GongfahomemakeData.lua":
            return "config_cache_builder", "Data layer builds the featureGroup/star lookup cache."
        if file_name == "GongfahomemakeModel.lua":
            return "model_lookup", "Model layer exposes featureGroup/star lookup to UI and manager code."
        if any(name in file_name for name in ("DetailView", "TipsView", "CreateView", "ComposeSuccessView")):
            return "display_formula_renderer", "UI code fetches the XianShu star row before rendering detail text."
        if file_name == "GongfahomemakeMgr.lua":
            return "display_or_quality_helper", "Manager uses the XianShu star row for display text or quality/name helpers."
        return "xianshu_star_lookup", "Lookup of XianShu star formula config."
    if term == "GetMainDes":
        if "gongfahomemake" in path_text or "gongfanew" in path_text:
            return "display_description_renderer", "Gongfa UI/manager renders config templates into visible description text."
        return "description_renderer", "Description renderer call."
    if term == "xianEffectMap":
        if "readmessagemap2dic" in line.lower():
            return "payload_read", "Protocol VO reads xianEffectMap from packet/runtime payload."
        if "write" in line.lower() and "xianeffectmap" in line.lower():
            return "payload_write_surface", "Generated or bridge code writes xianEffectMap; verify separately before treating as authority."
        if "/battle_" in path_text:
            return "battle_selection_context", "Battle presentation/selection code consumes xianEffectMap as already-known state."
        if "/message_" in path_text:
            return "payload_state_schema", "Protocol VO declares or carries xianEffectMap state."
        if "getxianshuqualitycfg" in line.lower() or "getcreatequalitycfg" in line.lower():
            return "quality_name_context", "UI/helper code derives quality/name display from xianEffectMap."
        if "getgongfaidarrcompare" in line.lower():
            return "skill_compare_context", "UI/battle helper compares active Gongfa ids using xianEffectMap."
        return "xian_effect_state_context", "xianEffectMap state consumer."
    return "unknown", ""


def _scan_xianshu_formula_lua_usage(export_base: Path, *, max_rows: int = 600) -> list[dict[str, object]]:
    root = export_base / "by_source" / "lscripts"
    if not root.is_dir():
        return []
    terms = [
        "LingjieGongfa_XianjieGongfaStar",
        "GetXianjieGongfaStarCfgEx",
        "GetMainDes",
        "xianEffectMap",
    ]
    rows: list[dict[str, object]] = []
    for path in sorted(root.rglob("*.lua"), key=lambda item: str(item).lower()):
        if "__" in path.stem:
            continue
        try:
            lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
        except OSError:
            continue
        for line_no, line in enumerate(lines, start=1):
            for term in terms:
                if term not in line:
                    continue
                usage_kind, interpretation = _classify_xianshu_formula_usage(path, term, line)
                rel_path = path.relative_to(export_base).as_posix() if path.is_relative_to(export_base) else str(path)
                rows.append(
                    {
                        "usage_kind": usage_kind,
                        "term": term,
                        "source_file": str(path),
                        "relative_path": rel_path,
                        "file": path.name,
                        "line": line_no,
                        "code": line.strip(),
                        "interpretation": interpretation,
                    }
                )
                if len(rows) >= max_rows:
                    return rows
    return rows


def _collect_xianshu_formula_logic_index_rows(export_base: Path) -> tuple[list[dict[str, object]], list[dict[str, object]]]:
    index_dir = export_base / "parsed_configs" / "lua_logic_index"
    config_rows: list[dict[str, object]] = []
    for row in _read_tsv_rows(index_dir / "config_refs.tsv"):
        if str(row.get("config_name", "")).strip() != "LingjieGongfa_XianjieGongfaStar":
            continue
        config_rows.append(
            {
                "usage_kind": "logic_index_config_ref",
                "term": row.get("config_name", ""),
                "source_file": row.get("relative_path", ""),
                "relative_path": row.get("relative_path", ""),
                "file": row.get("file", ""),
                "line": row.get("lines", ""),
                "code": f"ref_count={row.get('ref_count', '')}",
                "interpretation": "Lua logic index found the generated formula config reference.",
            }
        )

    wanted_functions = {"GetXianjieGongfaStarCfgEx", "GetMainFeatureCfgById", "GetSideFeatureJieCfgById", "GetMainDes"}
    function_rows: list[dict[str, object]] = []
    for row in _read_tsv_rows(index_dir / "functions.tsv"):
        if str(row.get("function_name", "")).strip() not in wanted_functions:
            continue
        function_rows.append(
            {
                "usage_kind": "logic_index_function",
                "term": row.get("function_name", ""),
                "source_file": row.get("relative_path", ""),
                "relative_path": row.get("relative_path", ""),
                "file": row.get("file", ""),
                "line": row.get("line", ""),
                "code": "",
                "interpretation": "Lua logic index exposed a function relevant to XianShu formula rendering.",
            }
        )
    return config_rows, function_rows


def _xianshu_formula_usage_checks(
    usage_rows: list[dict[str, object]],
    cpp2il_hits: list[dict[str, object]],
) -> list[dict[str, object]]:
    def count_where(predicate: Any) -> int:
        return sum(1 for row in usage_rows if predicate(row))

    formula_terms = {"LingjieGongfa_XianjieGongfaStar", "GetXianjieGongfaStarCfgEx", "XianjieGongfaStar"}

    def is_formula_combat_or_protocol(row: dict[str, object]) -> bool:
        path = str(row.get("relative_path") or row.get("source_file") or "").lower()
        term = str(row.get("term", ""))
        return term in formula_terms and any(marker in path for marker in ("/battle_", "/fight_", "/message_"))

    return [
        {
            "check": "formula_config_cache_refs",
            "hit_count": count_where(
                lambda row: str(row.get("term", "")) == "LingjieGongfa_XianjieGongfaStar"
            ),
            "status": "found",
            "interpretation": "XianjieGongfaStar config is visible as a generated config table and cache source.",
        },
        {
            "check": "formula_detail_renderer_refs",
            "hit_count": count_where(
                lambda row: str(row.get("usage_kind", ""))
                in {"display_formula_renderer", "display_description_renderer", "display_or_quality_helper"}
            ),
            "status": "found",
            "interpretation": "UI/manager code uses the formula rows to render visible Gongfa/XianShu text.",
        },
        {
            "check": "xian_effect_map_packet_reads",
            "hit_count": count_where(lambda row: str(row.get("usage_kind", "")) == "payload_read"),
            "status": "found",
            "interpretation": "xianEffectMap is read from protocol/runtime payload state.",
        },
        {
            "check": "formula_config_combat_or_protocol_refs",
            "hit_count": count_where(is_formula_combat_or_protocol),
            "status": "found" if count_where(is_formula_combat_or_protocol) else "not_found",
            "interpretation": "Direct formula config lookups in battle/fight/message layers would weaken the display-only boundary.",
        },
        {
            "check": "xian_effect_map_battle_context_refs",
            "hit_count": count_where(lambda row: str(row.get("usage_kind", "")) == "battle_selection_context"),
            "status": "found" if count_where(lambda row: str(row.get("usage_kind", "")) == "battle_selection_context") else "not_found",
            "interpretation": "Battle-side xianEffectMap references are tracked separately because they consume state, not XianjieGongfaStar templates.",
        },
        {
            "check": "cpp2il_formula_terms",
            "hit_count": len(cpp2il_hits),
            "status": "found" if cpp2il_hits else "not_found",
            "interpretation": "Cpp2IL hits for formula terms would suggest a native/bridge usage surface.",
        },
    ]


def build_fanxiu_gongfa_homemake_xianshu_formula_usage_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    """Trace whether XianShu formula config is display-only or used by runtime authority layers."""
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)

    lua_rows = _scan_xianshu_formula_lua_usage(export_base)
    config_index_rows, function_index_rows = _collect_xianshu_formula_logic_index_rows(export_base)
    usage_rows = config_index_rows + function_index_rows + lua_rows
    cpp2il_hits = _scan_cpp2il_term_hits(
        export_base,
        ["XianjieGongfaStar", "GetXianjieGongfaStar", "LingjieGongfa_XianjieGongfaStar", "xianEffectMap"],
        limit=120,
    )
    checks = _xianshu_formula_usage_checks(usage_rows, cpp2il_hits)
    by_check = {str(row["check"]): row for row in checks}

    formula_config_combat_or_protocol_hits = int(
        by_check.get("formula_config_combat_or_protocol_refs", {}).get("hit_count") or 0
    )
    detail_renderer_hits = int(by_check.get("formula_detail_renderer_refs", {}).get("hit_count") or 0)
    payload_read_hits = int(by_check.get("xian_effect_map_packet_reads", {}).get("hit_count") or 0)
    config_ref_files = {
        str(row.get("file") or Path(str(row.get("source_file", ""))).name)
        for row in usage_rows
        if str(row.get("term", "")) == "LingjieGongfa_XianjieGongfaStar"
    }

    usage_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_xianshu_formula_usage.tsv",
        ["usage_kind", "term", "source_file", "relative_path", "file", "line", "code", "interpretation"],
        usage_rows,
    )
    check_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_xianshu_formula_usage_checks.tsv",
        ["check", "hit_count", "status", "interpretation"],
        checks,
    )
    cpp2il_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_xianshu_formula_usage_cpp2il_hits.tsv",
        ["term", "source_root", "source_file", "line", "text"],
        cpp2il_hits,
    )

    usage_kinds = Counter(str(row.get("usage_kind", "")) for row in usage_rows)
    lines = [
        "# GongFaHomeMake 仙书公式引用面探针",
        "",
        f"- 导出目录：`{export_base}`",
        f"- Lua/索引命中：{usage_count}",
        f"- 检查项：{check_count}",
        f"- Cpp2IL 命中：{cpp2il_count}",
        "- 口径：区分 `XianjieGongfaStar.describe/param` 的展示渲染、`xianEffectMap` 的运行时状态承载，以及战斗/协议层是否直接读取公式配置。",
        "",
        "## 检查项",
        "",
        "| Check | Hits | Status | Meaning |",
        "| --- | ---: | --- | --- |",
    ]
    for row in checks:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('check', ''), limit=120)} | "
            f"{_markdown_table_cell(row.get('hit_count', ''), limit=40)} | "
            f"{_markdown_table_cell(row.get('status', ''), limit=60)} | "
            f"{_markdown_table_cell(row.get('interpretation', ''), limit=220)} |"
        )
    lines.extend(
        [
            "",
            "## 用法分类",
            "",
            "| Usage Kind | Count |",
            "| --- | ---: |",
        ]
    )
    for usage_kind, count in usage_kinds.most_common():
        lines.append(f"| {_markdown_table_cell(usage_kind, limit=120)} | {count} |")
    lines.extend(
        [
            "",
            "## 结论",
            "",
            "- `XianjieGongfaStar` 的可见主链路是 `GongfahomemakeData` 加载/缓存、`GongfahomemakeModel` 查询、UI/manager 调 `GetMainDes` 渲染详情文案。",
            "- `xianEffectMap` 是协议/运行时状态容器：消息 VO 从包里读出，UI/战斗表现侧拿它做显示、品质、功法 id 比较等消费。",
            "- 当前探针没有发现战斗/协议层直接读取 `XianjieGongfaStar` 公式配置来生产结果数值；这继续支持“公式文本是展示面，权威结算在更外层/服务端结果包”的边界。",
        ]
    )
    markdown_path = output_dir / "hot_update_gongfa_homemake_xianshu_formula_usage_report.md"
    markdown_path.write_text("\n".join(lines), encoding="utf-8")

    verdict = {
        "xianjie_star_config_loaded_only_by_homemake_data": bool(config_ref_files)
        and config_ref_files.issubset({"GongfahomemakeData.lua", "ConfigName.lua"}),
        "detail_renderer_uses_formula_template": detail_renderer_hits > 0,
        "xian_effect_map_is_server_payload_state": payload_read_hits > 0,
        "combat_or_protocol_formula_config_usage_found": formula_config_combat_or_protocol_hits > 0,
        "xian_effect_map_has_battle_consumers": int(by_check.get("xian_effect_map_battle_context_refs", {}).get("hit_count") or 0)
        > 0,
        "cpp2il_formula_usage_found": cpp2il_count > 0,
        "supports_display_surface_not_runtime_authority": (
            detail_renderer_hits > 0
            and payload_read_hits > 0
            and formula_config_combat_or_protocol_hits == 0
            and cpp2il_count == 0
        ),
    }
    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "counts": {
            "usage_rows": usage_count,
            "logic_index_config_refs": len(config_index_rows),
            "logic_index_functions": len(function_index_rows),
            "lua_usage_rows": len(lua_rows),
            "checks": check_count,
            "cpp2il_hits": cpp2il_count,
            "usage_kinds": dict(usage_kinds),
        },
        "verdict": verdict,
        "outputs": {
            "usage": str(output_dir / "hot_update_gongfa_homemake_xianshu_formula_usage.tsv"),
            "checks": str(output_dir / "hot_update_gongfa_homemake_xianshu_formula_usage_checks.tsv"),
            "cpp2il_hits": str(output_dir / "hot_update_gongfa_homemake_xianshu_formula_usage_cpp2il_hits.tsv"),
            "markdown": str(markdown_path),
            "json": str(output_dir / "hot_update_gongfa_homemake_xianshu_formula_usage_report.json"),
        },
    }
    (output_dir / "hot_update_gongfa_homemake_xianshu_formula_usage_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


