def _scan_xianshu_battle_state_usage_surface(export_base: Path, *, max_rows: int = 240) -> list[dict[str, object]]:
    root = export_base / "by_source" / "lscripts"
    if not root.is_dir():
        return []
    terms = ["IsSkillConflict", "GetGongFaIdArrCompare", "GongFaIdArr", "GetHaveSameEffect", "CompareGongFaIdArr"]
    rows: list[dict[str, object]] = []
    for path in sorted(root.rglob("*.lua"), key=lambda item: str(item).lower()):
        if "__" in path.stem:
            continue
        try:
            lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
        except OSError:
            continue
        path_text = path.as_posix().lower()
        if not any(marker in path_text for marker in ("/battle_", "/gongfanew_", "/gongfahomemake_", "/mainui_", "/core_")):
            continue
        for line_no, line in enumerate(lines, start=1):
            for term in terms:
                if term not in line:
                    continue
                if "/battle_" in path_text or "/core_" in path_text:
                    context = "battle_runtime_guard"
                elif "battle" in path.name.lower() or "tips" in path.name.lower() or "view" in path.name.lower():
                    context = "battle_setup_ui"
                elif "mgr" in path.name.lower():
                    context = "manager_identity_compare"
                else:
                    context = "state_context"
                rel_path = path.relative_to(export_base).as_posix() if path.is_relative_to(export_base) else str(path)
                rows.append(
                    {
                        "context": context,
                        "term": term,
                        "source_file": str(path),
                        "relative_path": rel_path,
                        "file": path.name,
                        "line": line_no,
                        "code": line.strip(),
                    }
                )
                if len(rows) >= max_rows:
                    return rows
    return rows


def build_fanxiu_gongfa_homemake_xianshu_battle_state_usage_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    """Explain battle-side xianEffectMap consumers without treating them as formula authority."""
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)

    flow_rows = _collect_xianshu_battle_state_usage_flow(export_base)
    surface_rows = _scan_xianshu_battle_state_usage_surface(export_base)
    formula_term_hits = [
        row
        for row in _scan_xianshu_formula_lua_usage(export_base, max_rows=300)
        if str(row.get("term", "")) in {"LingjieGongfa_XianjieGongfaStar", "GetXianjieGongfaStarCfgEx"}
        and any(
            marker in str(row.get("relative_path") or row.get("source_file") or "").lower()
            for marker in ("/battle_", "/fight_", "/message_")
        )
    ]
    contexts = Counter(str(row.get("context", "")) for row in surface_rows)
    checks = [
        {
            "check": "manual_or_auto_release_conflict_guard",
            "hit_count": sum(
                1 for row in surface_rows if row.get("term") == "IsSkillConflict" and row.get("context") == "battle_runtime_guard"
            ),
            "status": "found",
            "interpretation": "Battle runtime checks skill conflict before release.",
        },
        {
            "check": "xian_effect_map_identity_projection",
            "hit_count": sum(1 for row in surface_rows if row.get("term") == "GetGongFaIdArrCompare"),
            "status": "found",
            "interpretation": "xianEffectMap is routed through GongFaIdArr construction for identity/equipped-effect comparison.",
        },
        {
            "check": "same_effect_comparison_chain",
            "hit_count": sum(
                1 for row in surface_rows if row.get("term") in {"GetHaveSameEffect", "CompareGongFaIdArr"}
            ),
            "status": "found",
            "interpretation": "The downstream chain compares Gongfa ids; it does not expose numeric formula evaluation.",
        },
        {
            "check": "battle_formula_config_lookup",
            "hit_count": len(formula_term_hits),
            "status": "found" if formula_term_hits else "not_found",
            "interpretation": "Direct XianjieGongfaStar formula lookup in battle/fight/message layers would indicate formula authority; current scan expects none.",
        },
    ]
    flow_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_usage_flow.tsv",
        ["stage", "source_file", "lines", "fields", "role", "meaning", "formula_evidence", "code_excerpt"],
        flow_rows,
    )
    surface_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_usage_surface.tsv",
        ["context", "term", "source_file", "relative_path", "file", "line", "code"],
        surface_rows,
    )
    check_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_usage_checks.tsv",
        ["check", "hit_count", "status", "interpretation"],
        checks,
    )
    formula_hit_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_formula_hits.tsv",
        ["usage_kind", "term", "source_file", "relative_path", "file", "line", "code", "interpretation"],
        formula_term_hits,
    )
    lines = [
        "# GongFaHomeMake 仙书 battle-side 状态消费探针",
        "",
        f"- 导出目录：`{export_base}`",
        f"- Flow 行：{flow_count}",
        f"- Surface 行：{surface_count}",
        f"- 公式配置战斗层命中：{formula_hit_count}",
        "- 口径：解释 `xianEffectMap` 在 battle/runtime guard 中的用途，不把它和 `XianjieGongfaStar.describe/param` 公式模板混为一谈。",
        "",
        "## 检查项",
        "",
        "| Check | Hits | Status | Meaning |",
        "| --- | ---: | --- | --- |",
    ]
    for row in checks:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('check', ''), limit=120)} | "
            f"{_markdown_table_cell(row.get('hit_count', ''), limit=40)} | "
            f"{_markdown_table_cell(row.get('status', ''), limit=60)} | "
            f"{_markdown_table_cell(row.get('interpretation', ''), limit=220)} |"
        )
    lines.extend(["", "## Surface Contexts", "", "| Context | Count |", "| --- | ---: |"])
    for context, count in contexts.most_common():
        lines.append(f"| {_markdown_table_cell(context, limit=120)} | {count} |")
    lines.extend(
        [
            "",
            "## 结论",
            "",
            "- `SkillMgr.IsSkillConflict` 是当前明确的 battle-side `xianEffectMap` 消费点：它只在释放前构造 `GongFaIdArr` 并检查同类/重复功法效果。",
            "- `GongFaNewMgr.GetGongFaIdArrCompare` 将 `xianEffectMap` 的 skillId 转为 Gongfa id，属于身份/槽位比较，不读取 `SideFeatureJie.param` 或 `XianjieGongfaStar.describe/param`。",
            "- UI 装配页和预览页复用同一比较结构来显示冲突提示；这进一步说明它是装备/释放 guard，而不是伤害公式解释器。",
            "- 当前没有 battle/fight/message 层直接读取仙书公式配置的命中。",
        ]
    )
    markdown_path = output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_usage_report.md"
    markdown_path.write_text("\n".join(lines), encoding="utf-8")
    verdict = {
        "battle_consumes_xian_effect_map": any(row.get("context") == "battle_runtime_guard" for row in surface_rows),
        "battle_usage_is_conflict_guard": any(row.get("stage") == "battle_xian_effect_state_entry" for row in flow_rows),
        "xian_effect_map_projected_to_gongfa_id_array": any(
            row.get("stage") == "xian_effect_map_to_gongfa_id_array" for row in flow_rows
        ),
        "battle_formula_config_lookup_found": bool(formula_term_hits),
        "supports_state_consumer_not_formula_authority": bool(flow_rows) and not formula_term_hits,
    }
    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "counts": {
            "flow_rows": flow_count,
            "surface_rows": surface_count,
            "checks": check_count,
            "formula_hit_rows": formula_hit_count,
            "contexts": dict(contexts),
        },
        "verdict": verdict,
        "outputs": {
            "flow": str(output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_usage_flow.tsv"),
            "surface": str(output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_usage_surface.tsv"),
            "checks": str(output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_usage_checks.tsv"),
            "formula_hits": str(output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_formula_hits.tsv"),
            "markdown": str(markdown_path),
            "json": str(output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_usage_report.json"),
        },
    }
    (output_dir / "hot_update_gongfa_homemake_xianshu_battle_state_usage_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


