def _parse_lua_packet_field_rows(packet: str, path: Path | None, *, role: str) -> list[dict[str, object]]:
    if not path or not path.is_file():
        return []
    try:
        lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
    except OSError:
        return []

    rows: list[dict[str, object]] = []
    seen: set[tuple[str, str, str, int]] = set()
    for line_no, line in enumerate(lines, start=1):
        stripped = line.strip()
        matches: list[tuple[str, str, str]] = []
        for match in re.finditer(r"\bself\.([A-Za-z_]\w*)\s*=.*?\bself:read([A-Za-z_]\w*)\(", line):
            matches.append(("reading", match.group(1), f"read{match.group(2)}"))
        for match in re.finditer(r"\bself:read([A-Za-z_]\w*)\(self\.([A-Za-z_]\w*)", line):
            matches.append(("reading", match.group(2), f"read{match.group(1)}"))
        for match in re.finditer(r"\bself:write([A-Za-z_]\w*)\(self\.([A-Za-z_]\w*)", line):
            matches.append(("writing", match.group(2), f"write{match.group(1)}"))
        for direction, field, method in matches:
            key = (direction, field, method, line_no)
            if key in seen:
                continue
            seen.add(key)
            rows.append(
                {
                    "packet": packet,
                    "role": role,
                    "direction": direction,
                    "field": field,
                    "method": method,
                    "source_file": str(path),
                    "line": line_no,
                    "code": stripped,
                    "meaning": _xianshu_cast_packet_field_meaning(packet, role, field, method),
                }
            )
    return rows


def _xianshu_cast_packet_field_meaning(packet: str, role: str, field: str, method: str) -> str:
    if packet.startswith("CM_"):
        mapping = {
            "casterId": "request caster entity id",
            "skillId": "request selected skill id",
            "targetId": "request selected target id",
            "selectTargetIds": "request multi-target id list after local shape cast",
            "selectDir": "request selected direction",
            "selectPos": "request selected position",
            "movePos": "request movement target position",
            "currPos": "request current caster position",
        }
        return mapping.get(field, f"{role} request field")
    if packet == "SM_FightCast":
        mapping = {
            "id": "server cast instance id",
            "casterId": "server cast caster entity id",
            "skillId": "server cast skill id",
            "jie": "server-provided stage/jie used by cast presentation",
            "star": "server-provided star used by cast presentation",
            "cdTime": "server-provided cooldown",
            "attackPerSecond": "server-provided attack speed context",
            "fightCastVO": "server-provided cast selection/effect context",
            "currPos": "server-provided current position",
            "castingSpeed": "server-provided casting speed",
        }
        return mapping.get(field, f"{role} field")
    return f"{role} field"


