def _collect_gongfa_homemake_timeline_config_files(export_base: Path) -> dict[str, Path | None]:
    by_source = export_base / "by_source" / "lscripts"
    return {
        "skill_config_lua": _find_one_file(by_source, "gamesystem/game/luaconfig_*/text_assets/SkillConfig.lua"),
        "read_skill_config_lua": _find_one_file(by_source, "core_*/text_assets/ReadSkillConfig.lua"),
        "skill_table": _find_one_file(by_source, "generate/cfg/skill_*/text_assets/Skill.lua"),
        "skill_config_value": _find_one_file(by_source, "generate/cfg/skill_*/text_assets/ConfigValue.lua"),
        "timeline_dir": _find_text_asset_dir(export_base, "lscripts", "gamesystem", "game", module="luaconfig"),
    }


def _timeline_options(value: Any) -> list[str]:
    if value in (None, "", [], {}):
        return []
    if isinstance(value, (list, tuple)):
        return [str(item).strip() for item in value if str(item).strip()]
    return [str(value).strip()]


def _timeline_option_parts(option: str) -> tuple[str, int | None]:
    text = str(option).strip()
    if not text:
        return "", None
    if "|" in text:
        pieces = [piece.strip() for piece in text.split("|") if piece.strip()]
        if len(pieces) >= 2:
            return pieces[0], _hot_update_int(pieces[1])
    return "", _hot_update_int(text)


def _decode_timeline_tracks(total_json: Any) -> list[dict[str, Any]]:
    if not isinstance(total_json, str) or not total_json.strip():
        return []
    try:
        raw_tracks = json.loads(total_json)
    except json.JSONDecodeError:
        return []
    if not isinstance(raw_tracks, list):
        return []
    tracks: list[dict[str, Any]] = []
    for raw_track in raw_tracks:
        if isinstance(raw_track, str):
            try:
                track = json.loads(raw_track)
            except json.JSONDecodeError:
                continue
        elif isinstance(raw_track, dict):
            track = raw_track
        else:
            continue
        raw_value = track.get("TrackValue")
        if isinstance(raw_value, str):
            try:
                track_value = json.loads(raw_value)
            except json.JSONDecodeError:
                track_value = {}
        elif isinstance(raw_value, dict):
            track_value = raw_value
        else:
            track_value = {}
        clips = track_value.get("ClipDataList")
        if not isinstance(clips, list):
            clips = []
        tracks.append(
            {
                "track_name": track.get("TrackName", ""),
                "track_type": track_value.get("TracType", ""),
                "frame_count": track_value.get("FrameCount", ""),
                "total_time": track_value.get("TotalTime", ""),
                "clips": [clip for clip in clips if isinstance(clip, dict)],
            }
        )
    return tracks


def _summarize_timeline_track_rows(row: dict[str, Any]) -> dict[str, object]:
    attack_tracks = _decode_timeline_tracks(row.get("q_timeline_attacktrack"))
    suffer_tracks = _decode_timeline_tracks(row.get("q_timeline_suffertrack"))
    tracks = attack_tracks + suffer_tracks
    effect_paths: list[str] = []
    sound_ids: list[str] = []
    hit_frames: list[str] = []
    clip_types: list[str] = []
    track_names: list[str] = []
    for track in tracks:
        if track.get("track_name") not in ("", None):
            track_names.append(str(track.get("track_name", "")))
        for clip in track.get("clips", []):
            clip_type = clip.get("ClipType", "")
            if clip_type not in ("", None):
                clip_types.append(str(clip_type))
            args = clip.get("args")
            if not isinstance(args, dict):
                args = {}
            for key, value in args.items():
                key_text = str(key).lower()
                if "sound" in key_text and value not in ("", None, "None"):
                    sound_ids.append(str(value))
                if ("res" in key_text or "path" in key_text) and isinstance(value, str) and value and value != "None":
                    if value.startswith(("skill/", "effect/", "ui/", "avatar/", "model/")):
                        effect_paths.append(value)
            if str(clip_type) == "7" or "hurt" in json.dumps(args, ensure_ascii=False).lower():
                frame = args.get("Frame", clip.get("Start_Frame", ""))
                percent = args.get("Hurt_Precent", args.get("Hurt_Percent", ""))
                index = args.get("Hurt_Index", "")
                hit_frames.append(f"frame={frame},percent={percent},index={index}")
    for event in row.get("q_hurt_events") or []:
        if isinstance(event, list) and event:
            hit_frames.append("hurt_event=" + ",".join(str(item) for item in event[:4]))
    return {
        "display_name": row.get("q_timeline_displayName", ""),
        "description": row.get("q_desc", ""),
        "hurt_events": row.get("q_hurt_events", ""),
        "track_time": row.get("q_track_time", ""),
        "attack_track_count": len(attack_tracks),
        "suffer_track_count": len(suffer_tracks),
        "clip_count": sum(len(track.get("clips", [])) for track in tracks),
        "track_names": _unique_join(track_names, limit=12),
        "clip_types": _unique_join(clip_types, limit=16),
        "effect_paths": _unique_join(effect_paths, limit=16),
        "sound_ids": _unique_join(sound_ids, limit=12),
        "hit_frames": _unique_join(hit_frames, limit=16),
    }


def _parse_timeline_file_summary(timeline_id: int, timeline_dir: Path | None) -> dict[str, object]:
    if timeline_dir is None:
        return {
            "timeline_id": timeline_id,
            "timeline_file": "",
            "exists": False,
            "error": "timeline_dir_not_found",
        }
    path = timeline_dir / f"{timeline_id}.lua"
    if not path.is_file():
        return {
            "timeline_id": timeline_id,
            "timeline_file": str(path),
            "exists": False,
            "error": "timeline_file_not_found",
        }
    try:
        parsed = _parse_config(path, None)
    except Exception as exc:  # noqa: BLE001 - preserve malformed timeline evidence.
        return {
            "timeline_id": timeline_id,
            "timeline_file": str(path),
            "exists": True,
            "error": f"{type(exc).__name__}: {exc}",
        }
    first = parsed["rows"][0] if parsed.get("rows") else {}
    summary = _summarize_timeline_track_rows(first)
    summary.update(
        {
            "timeline_id": timeline_id,
            "timeline_file": str(path),
            "exists": True,
            "row_count": parsed.get("row_count", 0),
            "fields": " | ".join(str(item) for item in parsed.get("fields", [])),
            "error": "",
        }
    )
    return summary


def _collect_timeline_resolution_rows(
    skill_rows: list[dict[str, Any]],
    timeline_summaries: dict[int, dict[str, object]],
    *,
    max_skill_rows: int = 20000,
) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    scanned = 0
    for skill in skill_rows:
        if not any(_timeline_options(skill.get(rule["skill_field"])) for rule in _GONGFA_HOMEMAKE_TIMELINE_RULES):
            continue
        scanned += 1
        if scanned > max_skill_rows:
            break
        for rule in _GONGFA_HOMEMAKE_TIMELINE_RULES:
            field = str(rule["skill_field"])
            for option in _timeline_options(skill.get(field)):
                sex_condition, timeline_id = _timeline_option_parts(option)
                summary = timeline_summaries.get(int(timeline_id)) if timeline_id is not None else None
                rows.append(
                    {
                        "skill_id": skill.get("id", skill.get("_row_key", "")),
                        "skill_name": _plain(skill, "name"),
                        "context": rule["context"],
                        "runtime_condition": rule["runtime_condition"],
                        "skill_field": field,
                        "raw_option": option,
                        "sex_condition": sex_condition or "fallback/all",
                        "timeline_id": timeline_id or "",
                        "timeline_exists": bool(summary and summary.get("exists")),
                        "timeline_display_name": summary.get("display_name", "") if summary else "",
                        "timeline_desc": summary.get("description", "") if summary else "",
                        "hurt_events": summary.get("hurt_events", "") if summary else "",
                        "track_time": summary.get("track_time", "") if summary else "",
                        "attack_track_count": summary.get("attack_track_count", "") if summary else "",
                        "suffer_track_count": summary.get("suffer_track_count", "") if summary else "",
                        "clip_count": summary.get("clip_count", "") if summary else "",
                        "clip_types": summary.get("clip_types", "") if summary else "",
                        "hit_frames": summary.get("hit_frames", "") if summary else "",
                        "effect_paths": summary.get("effect_paths", "") if summary else "",
                        "sound_ids": summary.get("sound_ids", "") if summary else "",
                    }
                )
    return rows


def build_fanxiu_gongfa_homemake_stage_star_timeline_config_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    """Resolve SkillConfig stage/star timeline choices into concrete timeline config summaries."""
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)

    files = _collect_gongfa_homemake_timeline_config_files(export_base)
    lang_path = _find_lang_path(export_base)
    skill_rows = _parse_config(files["skill_table"], lang_path)["rows"]
    config_value_rows = _parse_config(files["skill_config_value"], lang_path)["rows"]
    config_value_by_id = {str(row.get("id", row.get("_row_key", ""))): row for row in config_value_rows}
    max_rank_threshold = str(config_value_by_id.get("CHANGE_TIMELINE_MIXRANK", {}).get("value", ""))

    timeline_ids: set[int] = set()
    variant_skill_count = 0
    for skill in skill_rows:
        has_variant = False
        for rule in _GONGFA_HOMEMAKE_TIMELINE_RULES:
            for option in _timeline_options(skill.get(rule["skill_field"])):
                _, timeline_id = _timeline_option_parts(option)
                if timeline_id is not None:
                    timeline_ids.add(int(timeline_id))
                    has_variant = True
        if has_variant:
            variant_skill_count += 1

    timeline_summaries = {
        timeline_id: _parse_timeline_file_summary(timeline_id, files["timeline_dir"])
        for timeline_id in sorted(timeline_ids)
    }
    resolution_rows = _collect_timeline_resolution_rows(skill_rows, timeline_summaries)

    skill_config_text = files["skill_config_lua"].read_text(encoding="utf-8", errors="ignore") if files["skill_config_lua"] else ""
    read_skill_config_text = (
        files["read_skill_config_lua"].read_text(encoding="utf-8", errors="ignore") if files["read_skill_config_lua"] else ""
    )
    rules = []
    for rule in _GONGFA_HOMEMAKE_TIMELINE_RULES:
        rules.append(
            {
                **rule,
                "source_file": str(files["skill_config_lua"] or ""),
                "max_rank_threshold": max_rank_threshold,
            }
        )

    checks = [
        {
            "check": "skillconfig_star_type_fields",
            "hit_count": sum(1 for field in ("jian_timelineId", "xian_timelineId", "mo_timelineId", "sha_timelineId") if field in skill_config_text),
            "status": "found" if all(field in skill_config_text for field in ("jian_timelineId", "xian_timelineId", "mo_timelineId", "sha_timelineId")) else "not_found",
            "interpretation": "SkillConfig maps GFType star values to four star-specific timeline fields.",
        },
        {
            "check": "max_rank_threshold_config",
            "hit_count": int("CHANGE_TIMELINE_MIXRANK" in skill_config_text and bool(max_rank_threshold)),
            "status": "found" if "CHANGE_TIMELINE_MIXRANK" in skill_config_text and max_rank_threshold else "not_found",
            "interpretation": "Stage-only max-rank switching is controlled by Skill_ConfigValue.CHANGE_TIMELINE_MIXRANK.",
        },
        {
            "check": "read_skill_config_decodes_tracks",
            "hit_count": int("q_timeline_attacktrack" in read_skill_config_text) + int("q_timeline_suffertrack" in read_skill_config_text),
            "status": "found" if "q_timeline_attacktrack" in read_skill_config_text and "q_timeline_suffertrack" in read_skill_config_text else "not_found",
            "interpretation": "ReadSkillConfig parses attack/suffer timeline JSON tracks into runtime timeline data.",
        },
        {
            "check": "skill_table_variant_rows",
            "hit_count": variant_skill_count,
            "status": "found" if variant_skill_count else "not_found",
            "interpretation": "Skill.Skill contains rows with stage/star timeline fields.",
        },
        {
            "check": "timeline_files_resolved",
            "hit_count": sum(1 for row in timeline_summaries.values() if row.get("exists")),
            "status": "found" if any(row.get("exists") for row in timeline_summaries.values()) else "not_found",
            "interpretation": "Concrete Lua timeline config files were resolved for referenced timeline ids.",
        },
        {
            "check": "timeline_track_json_decoded",
            "hit_count": sum(1 for row in timeline_summaries.values() if int(row.get("clip_count") or 0) > 0),
            "status": "found" if any(int(row.get("clip_count") or 0) > 0 for row in timeline_summaries.values()) else "not_found",
            "interpretation": "Timeline attack/suffer track JSON was decoded into clip/effect/hit-frame summaries.",
        },
    ]

    rule_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_rules.tsv",
        ["context", "skill_field", "runtime_condition", "meaning", "source_file", "max_rank_threshold"],
        rules,
    )
    resolution_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_resolution.tsv",
        [
            "skill_id",
            "skill_name",
            "context",
            "runtime_condition",
            "skill_field",
            "raw_option",
            "sex_condition",
            "timeline_id",
            "timeline_exists",
            "timeline_display_name",
            "timeline_desc",
            "hurt_events",
            "track_time",
            "attack_track_count",
            "suffer_track_count",
            "clip_count",
            "clip_types",
            "hit_frames",
            "effect_paths",
            "sound_ids",
        ],
        resolution_rows,
    )
    timeline_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_files.tsv",
        [
            "timeline_id",
            "exists",
            "timeline_file",
            "display_name",
            "description",
            "hurt_events",
            "track_time",
            "attack_track_count",
            "suffer_track_count",
            "clip_count",
            "track_names",
            "clip_types",
            "hit_frames",
            "effect_paths",
            "sound_ids",
            "fields",
            "error",
        ],
        timeline_summaries.values(),
    )
    check_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_checks.tsv",
        ["check", "hit_count", "status", "interpretation"],
        checks,
    )

    context_counts = Counter(str(row.get("context", "")) for row in resolution_rows)
    missing_timeline_count = sum(1 for row in timeline_summaries.values() if not row.get("exists"))
    lines = [
        "# GongFaHomeMake Stage/Star Timeline Config Probe",
        "",
        f"- Export root: `{export_base}`",
        f"- Rule rows: {rule_count}",
        f"- Skill timeline resolution rows: {resolution_count}",
        f"- Unique timeline files: {timeline_count}",
        f"- Missing timeline files: {missing_timeline_count}",
        f"- Checks: {check_count}",
        f"- Max-rank threshold: `{max_rank_threshold}`",
        "- Scope: resolves `SkillConfig.GetTimelineIdBySkillId(skillId, sex, stage, star)` into `Skill.Skill` timeline fields and concrete Lua timeline files.",
        "",
        "## Runtime Selection Rules",
        "",
        "| Context | Field | Condition | Meaning |",
        "| --- | --- | --- | --- |",
    ]
    for row in rules:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('context', ''), limit=80)} | "
            f"{_markdown_table_cell(row.get('skill_field', ''), limit=80)} | "
            f"{_markdown_table_cell(row.get('runtime_condition', ''), limit=160)} | "
            f"{_markdown_table_cell(row.get('meaning', ''), limit=180)} |"
        )
    lines.extend(["", "## Resolution Context Counts", "", "| Context | Rows |", "| --- | ---: |"])
    for context, count in context_counts.most_common():
        lines.append(f"| {_markdown_table_cell(context, limit=80)} | {count} |")
    lines.extend(["", "## Checks", "", "| Check | Hits | Status | Meaning |", "| --- | ---: | --- | --- |"])
    for row in checks:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('check', ''), limit=120)} | "
            f"{_markdown_table_cell(row.get('hit_count', ''), limit=40)} | "
            f"{_markdown_table_cell(row.get('status', ''), limit=60)} | "
            f"{_markdown_table_cell(row.get('interpretation', ''), limit=220)} |"
        )
    sample_rows = [row for row in resolution_rows if row.get("timeline_exists")][:12]
    lines.extend(
        [
            "",
            "## Sample Resolutions",
            "",
            "| Skill | Context | Option | Timeline | Desc | Hit Frames | Effects |",
            "| --- | --- | --- | --- | --- | --- | --- |",
        ]
    )
    for row in sample_rows:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('skill_id', ''), limit=70)} | "
            f"{_markdown_table_cell(row.get('context', ''), limit=70)} | "
            f"{_markdown_table_cell(row.get('raw_option', ''), limit=80)} | "
            f"{_markdown_table_cell(row.get('timeline_display_name', '') or row.get('timeline_id', ''), limit=100)} | "
            f"{_markdown_table_cell(row.get('timeline_desc', ''), limit=120)} | "
            f"{_markdown_table_cell(row.get('hit_frames', ''), limit=140)} | "
            f"{_markdown_table_cell(row.get('effect_paths', ''), limit=160)} |"
        )
    lines.extend(
        [
            "",
            "## Conclusion",
            "",
            "- `star` is the stronger selector: star `1/2/3/4` switches directly to `jian/xian/mo/sha_timelineId`.",
            "- Without a positive star, `stage` only switches to `maxRankTimelineId` after `CHANGE_TIMELINE_MIXRANK`; otherwise `timelineId` is used.",
            "- The resolved timeline Lua files contain presentation tracks, effect/sound resources and hit-frame metadata such as `q_hurt_events` or `ClipType=7`; this still describes playback/timing, not numeric combat formula authority.",
        ]
    )
    markdown_path = output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_report.md"
    markdown_path.write_text("\n".join(lines), encoding="utf-8")

    verdict = {
        "skillconfig_maps_star_to_variant_fields": checks[0]["status"] == "found",
        "max_rank_threshold_found": checks[1]["status"] == "found",
        "read_skill_config_decodes_tracks": checks[2]["status"] == "found",
        "skill_table_has_variant_rows": variant_skill_count > 0,
        "timeline_files_resolved": any(row.get("exists") for row in timeline_summaries.values()),
        "timeline_track_json_decoded": any(int(row.get("clip_count") or 0) > 0 for row in timeline_summaries.values()),
        "supports_config_resolution_to_timeline_playback_not_formula_authority": (
            checks[0]["status"] == "found"
            and checks[2]["status"] == "found"
            and variant_skill_count > 0
            and any(row.get("exists") for row in timeline_summaries.values())
        ),
    }
    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "counts": {
            "rules": rule_count,
            "resolution_rows": resolution_count,
            "unique_timeline_ids": len(timeline_summaries),
            "timeline_file_rows": timeline_count,
            "missing_timeline_files": missing_timeline_count,
            "variant_skill_rows": variant_skill_count,
            "checks": check_count,
            "contexts": dict(context_counts),
        },
        "verdict": verdict,
        "outputs": {
            "rules": str(output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_rules.tsv"),
            "resolution": str(output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_resolution.tsv"),
            "timeline_files": str(output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_files.tsv"),
            "checks": str(output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_checks.tsv"),
            "markdown": str(markdown_path),
            "json": str(output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_report.json"),
        },
    }
    (output_dir / "hot_update_gongfa_homemake_stage_star_timeline_config_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def _collect_gongfa_homemake_timeline_hurt_projection_files(export_base: Path) -> dict[str, Path | None]:
    by_source = export_base / "by_source" / "lscripts"
    return {
        "read_skill_config": _find_one_file(by_source, "core_*/text_assets/ReadSkillConfig.lua"),
        "skill_base": _find_one_file(by_source, "gamesystem/game/battle_*/text_assets/SkillBase.lua"),
        "hurt_frame_vo": _find_one_file(by_source, "gamesystem/game/battle_*/text_assets/HurtFrameVo.lua"),
        "hurt_data": _find_one_file(by_source, "gamesystem/game/battle_*/text_assets/HurtData.lua"),
    }


def _collect_timeline_hurt_projection_flow(files: dict[str, Path | None]) -> list[dict[str, object]]:
    return [
        {
            "stage": "timeline_track_json_decoded",
            "source_file": str(files["read_skill_config"] or ""),
            "lines": "120-150",
            "fields": "ClipType,args -> ClipData",
            "role": "timeline_clip_decode",
            "meaning": "`ReadSkillConfig` decodes timeline track JSON clips such as `ClipType=7` hurt-frame clips into runtime ClipData.",
            "formula_boundary": "timeline_clip_metadata",
            "code_excerpt": _source_excerpt(files["read_skill_config"], 120, 150),
        },
        {
            "stage": "skillbase_loads_timeline_hurt_events",
            "source_file": str(files["skill_base"] or ""),
            "lines": "286-299",
            "fields": "baseConfig.q_hurt_events -> self.Cfg_Hurts",
            "role": "timeline_hurt_event_load",
            "meaning": "`SkillBase.UpdateTimelineData` loads timeline hit events and sorts them before any server result is projected.",
            "formula_boundary": "timing_percent_metadata",
            "code_excerpt": _source_excerpt(files["skill_base"], 286, 299),
        },
        {
            "stage": "server_results_split_by_timeline_percent",
            "source_file": str(files["skill_base"] or ""),
            "lines": "359-445",
            "fields": "SM_FightResult.results -> FightResultVO -> percent*0.01 -> HurtData:SetData",
            "role": "result_projection",
            "meaning": "`SkillBase.SetSM_FightResult` loops `Cfg_Hurts`; each timeline event supplies time, percent and trajectory metadata used to split already-computed server result values.",
            "formula_boundary": "display_projection_not_formula",
            "code_excerpt": _source_excerpt(files["skill_base"], 359, 445),
        },
        {
            "stage": "hurtframe_schedules_or_executes",
            "source_file": str(files["hurt_frame_vo"] or ""),
            "lines": "20-92",
            "fields": "Add4HurtDataListDic(time), CheckHurt(elapseTime), ExecuteHurtDataList",
            "role": "hit_frame_scheduler",
            "meaning": "`HurtFrameVo` stores projected HurtData by timeline time and executes it when elapsed time reaches that frame.",
            "formula_boundary": "scheduler_not_formula",
            "code_excerpt": _source_excerpt(files["hurt_frame_vo"], 20, 92),
        },
        {
            "stage": "damage_times_visual_separation",
            "source_file": str(files["hurt_frame_vo"] or ""),
            "lines": "96-132",
            "fields": "damageTimes/hurtCount -> SeparateHurtData",
            "role": "multi_hit_display_split",
            "meaning": "`SeparateHurtData` divides projected values by hit count and schedules visual sub-hits over a duration.",
            "formula_boundary": "display_split_not_formula",
            "code_excerpt": _source_excerpt(files["hurt_frame_vo"], 96, 132),
        },
        {
            "stage": "hurtdata_consumes_projected_values",
            "source_file": str(files["hurt_data"] or ""),
            "lines": "79-150",
            "fields": "SetData -> Execute -> NormalExecute",
            "role": "display_value_consumer",
            "meaning": "`HurtData` stores projected display/result values and triggers visual HP/MP/floating text effects.",
            "formula_boundary": "consumer_not_formula",
            "code_excerpt": _source_excerpt(files["hurt_data"], 79, 150),
        },
    ]


def _scan_timeline_hurt_projection_surface(files: dict[str, Path | None]) -> list[dict[str, object]]:
    terms = [
        "q_hurt_events",
        "Cfg_Hurts",
        "hurt_event[1]",
        "hurt_event[2]",
        "hurt_event[3]",
        "hurt_event[4]",
        "percent*0.01",
        "resultVo.damage",
        "resultVo.damageView",
        "resultVo.damageTimes",
        "resultVo.recoverHp",
        "resultVo.damageReflect",
        "resultVo.mpAddDamage",
        "resultVo.mpAddDamageView",
        "HurtData:SetData",
        "Add4HurtDataListDic",
        "bullet:AddHurtData",
        "CheckHurt",
        "elapseTime>=time*0.001",
        "ExecuteHurtDataList",
        "SeparateHurtData",
        "clip_data.clip_type",
        "ClipType",
    ]
    rows: list[dict[str, object]] = []
    for source_key, path in files.items():
        if not path or not path.is_file():
            continue
        try:
            lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
        except OSError:
            continue
        for line_no, line in enumerate(lines, start=1):
            for term in terms:
                if term not in line:
                    continue
                rows.append(
                    {
                        "source_key": source_key,
                        "term": term,
                        "source_file": str(path),
                        "file": path.name,
                        "line": line_no,
                        "code": line.strip(),
                        "interpretation": _timeline_hurt_projection_interpretation(term),
                    }
                )
                break
    return rows


def _timeline_hurt_projection_interpretation(term: str) -> str:
    if term in {"q_hurt_events", "Cfg_Hurts", "hurt_event[1]", "hurt_event[2]", "hurt_event[3]", "hurt_event[4]"}:
        return "Timeline metadata supplies hit time, split percent and trajectory index."
    if "resultVo." in term:
        return "Already-computed server result field consumed by client projection."
    if term in {"HurtData:SetData", "Add4HurtDataListDic", "bullet:AddHurtData"}:
        return "Projected HurtData is scheduled for display/execution."
    if term in {"CheckHurt", "elapseTime>=time*0.001", "ExecuteHurtDataList", "SeparateHurtData"}:
        return "Runtime scheduler executes or visually splits projected HurtData."
    if term in {"clip_data.clip_type", "ClipType"}:
        return "Timeline clip metadata from exported track JSON."
    return "Timeline hurt projection surface."


def _load_timeline_hurt_projection_samples(export_base: Path, *, max_rows: int = 80) -> list[dict[str, object]]:
    config_path = export_base / "apk_static_index" / "hot_update_gongfa_homemake_stage_star_timeline_config_files.tsv"
    if not config_path.is_file():
        try:
            build_fanxiu_gongfa_homemake_stage_star_timeline_config_probe(export_root=export_base)
        except Exception:
            return []
    rows: list[dict[str, object]] = []
    for row in _read_tsv_rows(config_path):
        hit_frames = str(row.get("hit_frames", ""))
        if not hit_frames:
            continue
        rows.append(
            {
                "timeline_id": row.get("timeline_id", ""),
                "display_name": row.get("display_name", ""),
                "description": row.get("description", ""),
                "hurt_events": row.get("hurt_events", ""),
                "track_time": row.get("track_time", ""),
                "clip_count": row.get("clip_count", ""),
                "clip_types": row.get("clip_types", ""),
                "hit_frames": hit_frames,
                "effect_paths": row.get("effect_paths", ""),
                "timeline_file": row.get("timeline_file", ""),
            }
        )
        if len(rows) >= max_rows:
            break
    return rows


def _scan_timeline_hurt_formula_terms(flow_rows: list[dict[str, object]]) -> list[dict[str, object]]:
    formula_terms = [
        "BuffResource",
        "XianjieGongfaStar",
        "xianEffectMap",
        "featureGroup",
        "GetMainDes",
        "GetXianjieGongfaStarCfgEx",
        "SideFeatureJie",
        "FightResultVO.new",
        "GetMessageFromPools(_SM_FightResult",
        "F_SendMsg(_SM_FightResult",
    ]
    rows: list[dict[str, object]] = []
    for flow in flow_rows:
        text = str(flow.get("code_excerpt", ""))
        for line_offset, line in enumerate(text.splitlines(), start=1):
            for term in formula_terms:
                if term not in line:
                    continue
                rows.append(
                    {
                        "term": term,
                        "stage": flow.get("stage", ""),
                        "source_file": flow.get("source_file", ""),
                        "line_offset": line_offset,
                        "code": line.strip(),
                        "interpretation": "Formula/config-authority term appears inside the focused timeline hurt projection excerpt.",
                    }
                )
    return rows


def build_fanxiu_gongfa_homemake_timeline_hurt_projection_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    """Trace q_hurt_events/ClipType hurt metadata into HurtData projection without claiming formula authority."""
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)

    files = _collect_gongfa_homemake_timeline_hurt_projection_files(export_base)
    flow_rows = _collect_timeline_hurt_projection_flow(files)
    surface_rows = _scan_timeline_hurt_projection_surface(files)
    sample_rows = _load_timeline_hurt_projection_samples(export_base)
    formula_rows = _scan_timeline_hurt_formula_terms(flow_rows)
    flow_text = "\n".join(str(row.get("code_excerpt", "")) for row in flow_rows)
    surface_text = "\n".join(str(row.get("code", "")) for row in surface_rows)
    combined_text = flow_text + "\n" + surface_text
    checks = [
        {
            "check": "timeline_samples_include_hit_frames",
            "hit_count": len(sample_rows),
            "status": "found" if sample_rows else "not_found",
            "interpretation": "Decoded timeline config samples include q_hurt_events or ClipType=7 hit-frame metadata.",
        },
        {
            "check": "skillbase_loads_q_hurt_events",
            "hit_count": int("self.Cfg_Hurts=baseConfig.q_hurt_events" in combined_text) + int("table.sort(self.Cfg_Hurts" in combined_text),
            "status": "found" if "self.Cfg_Hurts=baseConfig.q_hurt_events" in combined_text else "not_found",
            "interpretation": "SkillBase loads hit timing/split metadata from selected timeline data.",
        },
        {
            "check": "fight_result_values_split_by_percent",
            "hit_count": combined_text.count("percent*0.01") + combined_text.count("resultVo.damageView"),
            "status": "found" if "resultVo.damageView" in combined_text and "percent*0.01" in combined_text else "not_found",
            "interpretation": "Server FightResultVO values are multiplied by timeline percent before HurtData storage.",
        },
        {
            "check": "hurtdata_scheduled_by_time_or_trajectory",
            "hit_count": int("Add4HurtDataListDic(time_ms" in combined_text) + int("bullet:AddHurtData" in combined_text),
            "status": "found" if "Add4HurtDataListDic(time_ms" in combined_text and "bullet:AddHurtData" in combined_text else "not_found",
            "interpretation": "Projected HurtData is keyed by timeline time or projectile trajectory index.",
        },
        {
            "check": "hurtframe_executes_by_elapsed_time",
            "hit_count": int("elapseTime>=time*0.001" in combined_text) + int("ExecuteHurtDataList" in combined_text),
            "status": "found" if "elapseTime>=time*0.001" in combined_text and "ExecuteHurtDataList" in combined_text else "not_found",
            "interpretation": "HurtFrameVo executes scheduled HurtData when playback reaches the configured hit time.",
        },
        {
            "check": "damage_times_visual_separation",
            "hit_count": int("SeparateHurtData" in combined_text) + int("hurtCount" in combined_text),
            "status": "found" if "SeparateHurtData" in combined_text and "hurtCount" in combined_text else "not_found",
            "interpretation": "Multi-hit display can split projected HurtData into scheduled sub-hits.",
        },
        {
            "check": "formula_authority_terms_in_focused_excerpt",
            "hit_count": len(formula_rows),
            "status": "found" if formula_rows else "not_found",
            "interpretation": "Formula/config-authority terms inside focused excerpts would weaken the projection-only boundary.",
        },
    ]

    flow_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_flow.tsv",
        ["stage", "source_file", "lines", "fields", "role", "meaning", "formula_boundary", "code_excerpt"],
        flow_rows,
    )
    surface_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_surface.tsv",
        ["source_key", "term", "source_file", "file", "line", "code", "interpretation"],
        surface_rows,
    )
    sample_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_samples.tsv",
        ["timeline_id", "display_name", "description", "hurt_events", "track_time", "clip_count", "clip_types", "hit_frames", "effect_paths", "timeline_file"],
        sample_rows,
    )
    formula_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_formula_terms.tsv",
        ["term", "stage", "source_file", "line_offset", "code", "interpretation"],
        formula_rows,
    )
    check_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_checks.tsv",
        ["check", "hit_count", "status", "interpretation"],
        checks,
    )

    contexts = Counter(str(row.get("source_key", "")) for row in surface_rows)
    verdict = {
        "timeline_samples_include_hit_frames": bool(sample_rows),
        "skillbase_loads_q_hurt_events": "self.Cfg_Hurts=baseConfig.q_hurt_events" in combined_text,
        "fight_result_values_split_by_percent": "resultVo.damageView" in combined_text and "percent*0.01" in combined_text,
        "hurtdata_scheduled_by_time_or_trajectory": "Add4HurtDataListDic(time_ms" in combined_text and "bullet:AddHurtData" in combined_text,
        "hurtframe_executes_by_elapsed_time": "elapseTime>=time*0.001" in combined_text and "ExecuteHurtDataList" in combined_text,
        "damage_times_visual_separation": "SeparateHurtData" in combined_text and "hurtCount" in combined_text,
        "formula_authority_terms_in_focused_excerpt_found": bool(formula_rows),
    }
    verdict["supports_timeline_hurt_projection_not_formula_authority"] = (
        verdict["skillbase_loads_q_hurt_events"]
        and verdict["fight_result_values_split_by_percent"]
        and verdict["hurtdata_scheduled_by_time_or_trajectory"]
        and verdict["hurtframe_executes_by_elapsed_time"]
        and not verdict["formula_authority_terms_in_focused_excerpt_found"]
    )
    lines = [
        "# GongFaHomeMake Timeline Hurt Projection Probe",
        "",
        f"- Export root: `{export_base}`",
        f"- Flow rows: {flow_count}",
        f"- Focused surface rows: {surface_count}",
        f"- Timeline hit-frame sample rows: {sample_count}",
        f"- Formula-authority terms in focused excerpts: {formula_count}",
        f"- Checks: {check_count}",
        "- Scope: follows `q_hurt_events` and timeline hurt clips into `SkillBase.SetSM_FightResult`, `HurtFrameVo`, and `HurtData`.",
        "",
        "## Checks",
        "",
        "| Check | Hits | Status | Meaning |",
        "| --- | ---: | --- | --- |",
    ]
    for row in checks:
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('check', ''), limit=120)} | "
            f"{_markdown_table_cell(row.get('hit_count', ''), limit=40)} | "
            f"{_markdown_table_cell(row.get('status', ''), limit=60)} | "
            f"{_markdown_table_cell(row.get('interpretation', ''), limit=240)} |"
        )
    lines.extend(["", "## Surface Contexts", "", "| Source | Rows |", "| --- | ---: |"])
    for context, count in contexts.most_common():
        lines.append(f"| {_markdown_table_cell(context, limit=80)} | {count} |")
    lines.extend(
        [
            "",
            "## Conclusion",
            "",
            "- `q_hurt_events` supplies hit time, percent split, trajectory flag and trajectory index; it is loaded from the selected timeline into `SkillBase.Cfg_Hurts`.",
            "- `SkillBase.SetSM_FightResult` consumes server `FightResultVO` values and multiplies display/numeric values by the timeline percent before creating `HurtData`.",
            "- `HurtFrameVo` executes the projected `HurtData` at playback time, or visually separates multi-hit display via `SeparateHurtData`.",
            "- Current focused excerpts do not reference `BuffResource/XianjieGongfaStar/xianEffectMap/featureGroup` formula config or any client-side `SM_FightResult` producer; this is a hit-frame/display projection layer, not numeric formula authority.",
        ]
    )
    markdown_path = output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_report.md"
    markdown_path.write_text("\n".join(lines), encoding="utf-8")

    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "counts": {
            "flow_rows": flow_count,
            "surface_rows": surface_count,
            "sample_rows": sample_count,
            "formula_term_rows": formula_count,
            "checks": check_count,
            "surface_contexts": dict(contexts),
        },
        "verdict": verdict,
        "outputs": {
            "flow": str(output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_flow.tsv"),
            "surface": str(output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_surface.tsv"),
            "samples": str(output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_samples.tsv"),
            "formula_terms": str(output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_formula_terms.tsv"),
            "checks": str(output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_checks.tsv"),
            "markdown": str(markdown_path),
            "json": str(output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_report.json"),
        },
    }
    (output_dir / "hot_update_gongfa_homemake_timeline_hurt_projection_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def _is_gongfa_homemake_symbol(name: str, module: str = "") -> bool:
    lower_module = str(module or "").lower()
    return (
        "gongfahomemake" in lower_module
        or "GongFaHomeMake" in str(name or "")
        or str(name or "")
        in {
            "GongFaHomeMakeVO",
            "GongFaHomeMakeListVO",
            "GongFaHomeMakeRecordVO",
            "GongFaHomeMakeScopeListVO",
            "GongFaHomeMakeShareVO",
            "CreateSkillCommonVO",
            "GongFaLearnItemVO",
            "GongFaTeachItemVO",
            "HMFilterVO",
        }
    )


def _summary_from_rows(
    rows: Iterable[dict[str, str]],
    fields: list[str],
    *,
    limit: int = 8,
    sep: str = " | ",
) -> str:
    values: list[str] = []
    for row in rows:
        parts = [str(row.get(field, "")).strip() for field in fields if str(row.get(field, "")).strip()]
        if parts:
            values.append(":".join(parts))
    return _unique_join(values, limit=limit, sep=sep)


def _homemake_state_needles(packet: str, operation: str) -> list[str]:
    needles = [packet, operation]
    mapping = {
        "SM_GongFaHomeMakeList": ["SetGongFaHomeMakeList", "homeMakeDic"],
        "SM_GongFaHomeMakePageList": ["homeMakeVOS", "homeMakeVOList"],
        "SM_UpdateGongFaHomeMakeLearn": ["UpdateGongFaHomeMakeLearn", "AddNewMakeSkill", "newMakeSkillDic"],
        "SM_UpdateGongFaHomeMakeLearnStatus": ["UpdateGongFaHomeMakeLearn", "skillCommonVO"],
        "SM_UpdateGongFaHomeMakeTeach": ["UpdateGongFaHomeMakeTeach"],
        "SM_GongFaHomeMakeCombine": ["GongFaHomeMakeCombine", "GongFaHomeMakeCombineUpdate", "AddNewMakeSkill"],
        "SM_GongFaHomeMakeCombineList": ["GongFaHomeMakeCombineList", "GongFaHomeMakeCombineUpdate", "V_CreatingSkillIdList"],
        "SM_GongFaHomeMakeChangeName": ["GongFaHomeMakeChangeName", "homeMakeVO"],
        "SM_GongFaHomeMakeChangeNameList": ["GongFaHomeMakeChangeNameList", "GongFaHomeMakeCombineUpdate"],
        "SM_GongFaCheck": ["GongFaCheck", "homeMakeDic"],
    }
    needles.extend(mapping.get(packet, []))
    if operation:
        needles.append(operation.replace("GongFaHomeMake", ""))
    return [needle for needle in needles if needle]


def _homemake_state_evidence(
    rows: list[dict[str, str]],
    *,
    packet: str,
    operation: str,
    limit: int = 8,
) -> str:
    needles = _homemake_state_needles(packet, operation)
    matches: list[dict[str, str]] = []
    for row in rows:
        haystack = "\n".join(
            [
                row.get("function_name", ""),
                row.get("code", ""),
                row.get("stage", ""),
                row.get("terms", ""),
            ]
        )
        if any(needle and needle in haystack for needle in needles):
            matches.append(row)
    return _summary_from_rows(matches, ["file", "function_name", "line", "code"], limit=limit)


def _homemake_ui_consumers(
    rows: list[dict[str, str]],
    *,
    packet: str,
    target_vo_refs: str,
    limit: int = 8,
) -> str:
    if not (
        "GongFaHomeMakeVO" in packet
        or "GongFaHomeMakeVO" in target_vo_refs
        or "CreateSkillCommonVO" in target_vo_refs
        or packet in {"CreateSkillCommonVO", "GongFaHomeMakeVO"}
    ):
        return ""
    matches = [
        row
        for row in rows
        if row.get("term") in {"gongFaHomeMakeVO", "makeId", "GetGongFaHomeMakeVoById"}
    ]
    return _summary_from_rows(matches, ["file", "function_name", "line", "code"], limit=limit)


def _gongfa_homemake_semantic_note(
    *,
    packet: str,
    direction: str,
    operation: str,
    target_vo_refs: str,
    state_evidence: str,
) -> str:
    if direction == "client_to_server":
        return f"客户端提交自创功法 {operation or packet} 意图；创建、筛选、命名、学习、上传等最终结果以后续服务端回包为准。"
    if direction == "server_to_client":
        if "GongFaHomeMakeVO" in target_vo_refs:
            return "服务端回写自创功法完整对象或列表；客户端把对象写入自创功法缓存，战斗/上阵侧再用 makeId 回查。"
        if state_evidence:
            return "服务端回包触发客户端自创功法状态刷新。"
        return "服务端回写自创功法相关结果或通知。"
    if packet == "CreateSkillCommonVO":
        return "`CreateSkillCommonVO.id` 是自创功法实例 id，战斗侧常以 makeId 形式携带并回查完整 `GongFaHomeMakeVO`。"
    if packet == "GongFaHomeMakeVO":
        return "自创功法核心值对象；包含 `skillCommonVO`、来源玩家、可见/勾选/创建状态和类型信息。"
    if direction == "value_object":
        return "自创功法链路中的嵌套值对象。"
    return "自创功法链路辅助结构。"


def _collect_gongfa_homemake_lifecycle_rows(
    export_base: Path,
) -> tuple[list[dict[str, object]], list[dict[str, object]]]:
    protocol_rows = _read_tsv_rows(export_base / "parsed_configs" / "lua_packet_index" / "protocol_gongfa.tsv")
    lingjie_dir = export_base / "parsed_configs" / "lingjie_feature_catalog"
    runtime_packet_rows = _read_tsv_rows(lingjie_dir / "lingjie_runtime_packets.tsv")
    vo_usage_rows = _read_tsv_rows(lingjie_dir / "lingjie_runtime_vo_usage.tsv")
    vo_field_rows = _read_tsv_rows(lingjie_dir / "lingjie_runtime_vo_fields.tsv")
    net_function_rows = _read_tsv_rows(lingjie_dir / "lingjie_runtime_net_functions.tsv")
    net_call_rows = _read_tsv_rows(lingjie_dir / "lingjie_runtime_net_call_sites.tsv")
    state_rows = _read_tsv_rows(lingjie_dir / "lingjie_runtime_state_updates.tsv")
    battle_rows = _read_tsv_rows(lingjie_dir / "lingjie_runtime_battle_refs.tsv")

    relevant_names = {
        row.get("name", "")
        for row in protocol_rows
        if _is_gongfa_homemake_symbol(row.get("name", ""), row.get("module", ""))
    }
    changed = True
    while changed:
        changed = False
        for row in vo_usage_rows:
            source = row.get("source_name", "")
            target = row.get("target_vo", "")
            if not source or not target:
                continue
            if source in relevant_names and target not in relevant_names:
                relevant_names.add(target)
                changed = True
            if target in relevant_names and source not in relevant_names:
                relevant_names.add(source)
                changed = True

    protocol_by_packet = {row.get("name", ""): row for row in protocol_rows}
    runtime_by_packet = {row.get("name", ""): row for row in runtime_packet_rows}
    net_by_packet: dict[str, dict[str, str]] = {}
    for row in net_function_rows:
        packet = row.get("packet_name", "")
        if packet and packet not in net_by_packet:
            net_by_packet[packet] = row
    call_sites_by_packet: dict[str, list[dict[str, str]]] = {}
    for row in net_call_rows:
        packet = row.get("packet_name", "")
        if packet:
            call_sites_by_packet.setdefault(packet, []).append(row)
    vo_usage_by_source: dict[str, list[dict[str, str]]] = {}
    for row in vo_usage_rows:
        source = row.get("source_name", "")
        if source:
            vo_usage_by_source.setdefault(source, []).append(row)

    operation_packets: dict[str, dict[str, list[str]]] = {}
    for row in protocol_rows:
        packet = row.get("name", "")
        if packet not in relevant_names:
            continue
        operation = _gongfa_operation_from_packet(packet)
        if not operation:
            continue
        direction = row.get("direction", "")
        bucket = operation_packets.setdefault(operation, {"client_to_server": [], "server_to_client": []})
        if direction in bucket:
            bucket[direction].append(packet)

    lifecycle_rows: list[dict[str, object]] = []
    for row in protocol_rows:
        packet = row.get("name", "")
        if packet not in relevant_names:
            continue
        direction = row.get("direction", "")
        operation = _gongfa_operation_from_packet(packet)
        runtime_row = runtime_by_packet.get(packet, {})
        net_row = net_by_packet.get(packet, {})
        target_vo_refs = _unique_join(
            (
                f"{item.get('field_name', '')}->{item.get('target_vo', '')}({item.get('read_method', '')})"
                for item in vo_usage_by_source.get(packet, [])
            ),
            limit=14,
        )
        state_evidence = _homemake_state_evidence(
            state_rows,
            packet=packet,
            operation=operation,
            limit=8,
        )
        ui_consumers = _homemake_ui_consumers(
            battle_rows,
            packet=packet,
            target_vo_refs=target_vo_refs,
            limit=8,
        )
        lifecycle_rows.append(
            {
                "id": row.get("id", ""),
                "packet": packet,
                "direction": direction,
                "module": row.get("module", ""),
                "packet_role": runtime_row.get("packet_role", ""),
                "operation": operation,
                "fields": row.get("write_fields", "") or row.get("read_fields", "") or runtime_row.get("fields", ""),
                "handler_names": row.get("handler_names", ""),
                "net_function": net_row.get("net_function", "") or (f"{packet}Fun" if direction == "client_to_server" else row.get("handler_names", "")),
                "net_fields_written": net_row.get("fields_written", ""),
                "call_sites": _summary_from_rows(
                    call_sites_by_packet.get(packet, []),
                    ["file", "function_name", "line", "code"],
                    limit=8,
                ),
                "target_vo_refs": target_vo_refs,
                "state_evidence": state_evidence,
                "ui_consumers": ui_consumers,
                "semantic_note": _gongfa_homemake_semantic_note(
                    packet=packet,
                    direction=direction,
                    operation=operation,
                    target_vo_refs=target_vo_refs,
                    state_evidence=state_evidence,
                ),
                "sample_files": row.get("sample_files", "") or runtime_row.get("file", ""),
            }
        )

    edges: list[dict[str, object]] = []
    for operation, packets in operation_packets.items():
        for client_packet in packets.get("client_to_server", []):
            edges.append(
                {
                    "source_type": "operation",
                    "source": operation,
                    "edge": "sends",
                    "target_type": "client_packet",
                    "target": client_packet,
                    "evidence": protocol_by_packet.get(client_packet, {}).get("write_fields", ""),
                }
            )
            for call_row in call_sites_by_packet.get(client_packet, [])[:8]:
                edges.append(
                    {
                        "source_type": "lua_call_site",
                        "source": f"{call_row.get('file', '')}:{call_row.get('function_name', '')}:{call_row.get('line', '')}",
                        "edge": "calls_net_function",
                        "target_type": "net_function",
                        "target": call_row.get("net_function", ""),
                        "evidence": call_row.get("code", ""),
                    }
                )
        for server_packet in packets.get("server_to_client", []):
            if packets.get("client_to_server"):
                for client_packet in packets.get("client_to_server", []):
                    edges.append(
                        {
                            "source_type": "client_packet",
                            "source": client_packet,
                            "edge": "paired_with",
                            "target_type": "server_packet",
                            "target": server_packet,
                            "evidence": operation,
                        }
                    )
            else:
                edges.append(
                    {
                        "source_type": "operation",
                        "source": operation,
                        "edge": "pushes",
                        "target_type": "server_packet",
                        "target": server_packet,
                        "evidence": "server push or notification",
                    }
                )
            handler = protocol_by_packet.get(server_packet, {}).get("handler_names", "")
            if handler:
                edges.append(
                    {
                        "source_type": "server_packet",
                        "source": server_packet,
                        "edge": "dispatches",
                        "target_type": "handler",
                        "target": handler,
                        "evidence": protocol_by_packet.get(server_packet, {}).get("read_fields", ""),
                    }
                )

    for row in vo_usage_rows:
        source = row.get("source_name", "")
        target = row.get("target_vo", "")
        if source in relevant_names and target in relevant_names:
            edges.append(
                {
                    "source_type": "packet_or_vo",
                    "source": source,
                    "edge": "carries_value_object",
                    "target_type": "value_object",
                    "target": target,
                    "evidence": f"{row.get('field_name', '')}:{row.get('read_method', '')}",
                }
            )

    if any(row.get("function_name") == "SetGongFaHomeMakeList" for row in state_rows):
        edges.append(
            {
                "source_type": "server_field",
                "source": "SM_GongFaHomeMakeList.homeMakeVOS",
                "edge": "replaces_cache",
                "target_type": "data_state",
                "target": "GongfahomemakeData.homeMakeDic",
                "evidence": "self.homeMakeDic=msg.homeMakeVOS",
            }
        )
    if any("UpdateGongFaHomeMakeLearn" in row.get("function_name", "") for row in state_rows):
        edges.append(
            {
                "source_type": "server_field",
                "source": "SM_UpdateGongFaHomeMakeLearn.homeMakeVO",
                "edge": "adds_or_updates_instance",
                "target_type": "data_state",
                "target": "GongfahomemakeData:AddNewMakeSkill/newMakeSkillDic",
                "evidence": "UpdateGongFaHomeMakeLearn -> AddNewMakeSkill",
            }
        )
    if any("GongFaHomeMakeCombineUpdate" in row.get("function_name", "") for row in state_rows):
        edges.append(
            {
                "source_type": "server_field",
                "source": "SM_GongFaHomeMakeCombine.homeMakeVO",
                "edge": "updates_creating_and_new_skill_cache",
                "target_type": "data_state",
                "target": "GongfahomemakeData:GongFaHomeMakeCombineUpdate/V_CreatingSkillIdList",
                "evidence": "combine 回包进入 GongFaHomeMakeCombineUpdate",
            }
        )
    if any(row.get("vo_name") == "CreateSkillCommonVO" and row.get("field_name") == "id" for row in vo_field_rows):
        edges.append(
            {
                "source_type": "value_object_field",
                "source": "GongFaHomeMakeVO.skillCommonVO.id",
                "edge": "becomes_lookup_key",
                "target_type": "runtime_key",
                "target": "makeId",
                "evidence": "CreateSkillCommonVO.id semantics: 自创功法实例 id / make id",
            }
        )
    if any("GetGongFaHomeMakeVoById" in row.get("function_name", "") for row in state_rows + battle_rows):
        edges.append(
            {
                "source_type": "runtime_key",
                "source": "makeId",
                "edge": "resolves_via",
                "target_type": "model_method",
                "target": "GongfahomemakeModel:GetGongFaHomeMakeVoById",
                "evidence": "战斗/上阵侧携带 makeId 后回查完整 GongFaHomeMakeVO",
            }
        )
    if any(row.get("category") == "battle_equip_ui" for row in battle_rows):
        edges.append(
            {
                "source_type": "value_object",
                "source": "GongFaHomeMakeVO",
                "edge": "consumed_by",
                "target_type": "ui_runtime",
                "target": "GongFaBattleCustomView/SelfGongFaBattleItem",
                "evidence": "battle_equip_ui rows reference gongFaHomeMakeVO and makeId",
            }
        )

    seen_edges: set[tuple[str, str, str, str, str, str]] = set()
    deduped_edges: list[dict[str, object]] = []
    for row in edges:
        key = (
            str(row.get("source_type", "")),
            str(row.get("source", "")),
            str(row.get("edge", "")),
            str(row.get("target_type", "")),
            str(row.get("target", "")),
            str(row.get("evidence", "")),
        )
        if key in seen_edges:
            continue
        seen_edges.add(key)
        deduped_edges.append(row)
    lifecycle_rows.sort(key=lambda item: (str(item.get("direction", "")), str(item.get("packet_role", "")), str(item.get("packet", ""))))
    return lifecycle_rows, deduped_edges


def _write_gongfa_homemake_lifecycle_markdown(
    path: Path,
    *,
    export_base: Path,
    lifecycle_rows: list[dict[str, object]],
    edge_rows: list[dict[str, object]],
) -> None:
    role_counts = Counter(str(row.get("packet_role", "")) for row in lifecycle_rows)
    direction_counts = Counter(str(row.get("direction", "")) for row in lifecycle_rows)
    lines = [
        "# GongFaHomeMake 自创功法生命周期",
        "",
        f"- 导出目录：`{export_base}`",
        f"- 主表行：{len(lifecycle_rows)}；语义边：{len(edge_rows)}",
        f"- 方向统计：{', '.join(f'{name or '<empty>'}:{count}' for name, count in direction_counts.most_common())}",
        f"- 角色统计：{', '.join(f'{name or '<empty>'}:{count}' for name, count in role_counts.most_common())}",
        "- 结论：`GongFaHomeMakeVO` 是客户端侧自创功法的完整对象；服务端回包写入 `homeMakeDic/newMakeSkillDic/V_CreatingSkillIdList` 等缓存后，战斗和上阵界面常只携带 `makeId`，再通过 `GetGongFaHomeMakeVoById` 回查完整对象。",
        "",
        "## Packet / VO 主表",
        "",
        "| packet | 方向 | 角色 | 操作 | 字段 | 网络函数 | VO 引用 | 状态证据 | UI 消费 | 说明 |",
        "| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    for row in lifecycle_rows:
        net = _unique_join([row.get("net_function", ""), row.get("net_fields_written", ""), row.get("call_sites", "")], limit=5)
        lines.append(
            "| "
            f"{_markdown_table_cell(row.get('packet', ''), limit=180)} | "
            f"{_markdown_table_cell(row.get('direction', ''), limit=80)} | "
            f"{_markdown_table_cell(row.get('packet_role', ''), limit=100)} | "
            f"{_markdown_table_cell(row.get('operation', ''), limit=130)} | "
            f"{_markdown_table_cell(row.get('fields', ''), limit=240)} | "
            f"{_markdown_table_cell(net, limit=280)} | "
            f"{_markdown_table_cell(row.get('target_vo_refs', ''), limit=280)} | "
            f"{_markdown_table_cell(row.get('state_evidence', ''), limit=320)} | "
            f"{_markdown_table_cell(row.get('ui_consumers', ''), limit=280)} | "
            f"{_markdown_table_cell(row.get('semantic_note', ''), limit=360)} |"
        )

    lines.extend(["", "## 语义边", "", "| 源 | 关系 | 目标 | 证据 |", "| --- | --- | --- | --- |"])
    for row in edge_rows:
        source = f"{row.get('source_type', '')}:{row.get('source', '')}"
        target = f"{row.get('target_type', '')}:{row.get('target', '')}"
        lines.append(
            "| "
            f"{_markdown_table_cell(source, limit=240)} | "
            f"{_markdown_table_cell(row.get('edge', ''), limit=150)} | "
            f"{_markdown_table_cell(target, limit=260)} | "
            f"{_markdown_table_cell(row.get('evidence', ''), limit=340)} |"
        )

    lines.extend(
        [
            "",
            "## 边界",
            "",
            "- 该报告证明的是客户端 Lua 如何发送意图、接收对象、落缓存和被 UI/战斗引用；不证明服务端如何生成或校验自创功法。",
            "- `CM_*` 行是客户端请求意图；`SM_*` 行和嵌套 VO 才是客户端实际应用到本地状态的来源。",
            "- `makeId` 当前可静态追到 `CreateSkillCommonVO.id` 与 `GetGongFaHomeMakeVoById`，后续可以继续把它接到战斗方案/上阵协议。",
            "",
            "## Outputs",
            "",
            "- `hot_update_gongfa_homemake_lifecycle_packets.tsv`：自创功法 packet/VO -> net/state/UI 的主表。",
            "- `hot_update_gongfa_homemake_lifecycle_edges.tsv`：operation/packet/VO/cache/makeId/UI 的边表。",
        ]
    )
    path.write_text("\n".join(lines), encoding="utf-8")


def build_fanxiu_gongfa_homemake_lifecycle_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)
    protocol_path = export_base / "parsed_configs" / "lua_packet_index" / "protocol_gongfa.tsv"
    if not protocol_path.is_file():
        build_fanxiu_lua_packet_index(export_root=export_base)
    lingjie_dir = export_base / "parsed_configs" / "lingjie_feature_catalog"
    required_runtime_files = [
        lingjie_dir / "lingjie_runtime_packets.tsv",
        lingjie_dir / "lingjie_runtime_vo_usage.tsv",
        lingjie_dir / "lingjie_runtime_vo_fields.tsv",
        lingjie_dir / "lingjie_runtime_net_functions.tsv",
        lingjie_dir / "lingjie_runtime_net_call_sites.tsv",
        lingjie_dir / "lingjie_runtime_state_updates.tsv",
        lingjie_dir / "lingjie_runtime_battle_refs.tsv",
    ]
    if not all(path.is_file() for path in required_runtime_files):
        from backend.core.fanxiu.catalog.lua_logic_index import build_fanxiu_lingjie_gongfa_runtime_report

        build_fanxiu_lingjie_gongfa_runtime_report(export_root=export_base)

    lifecycle_rows, edge_rows = _collect_gongfa_homemake_lifecycle_rows(export_base)
    packet_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_lifecycle_packets.tsv",
        [
            "id",
            "packet",
            "direction",
            "module",
            "packet_role",
            "operation",
            "fields",
            "handler_names",
            "net_function",
            "net_fields_written",
            "call_sites",
            "target_vo_refs",
            "state_evidence",
            "ui_consumers",
            "semantic_note",
            "sample_files",
        ],
        lifecycle_rows,
    )
    edge_count = _write_tsv(
        output_dir / "hot_update_gongfa_homemake_lifecycle_edges.tsv",
        ["source_type", "source", "edge", "target_type", "target", "evidence"],
        edge_rows,
    )
    _write_gongfa_homemake_lifecycle_markdown(
        output_dir / "hot_update_gongfa_homemake_lifecycle_report.md",
        export_base=export_base,
        lifecycle_rows=lifecycle_rows,
        edge_rows=edge_rows,
    )
    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "counts": {
            "packet_rows": packet_count,
            "edge_rows": edge_count,
            "by_direction": dict(Counter(str(row.get("direction", "")) for row in lifecycle_rows).most_common()),
            "by_role": dict(Counter(str(row.get("packet_role", "")) for row in lifecycle_rows).most_common()),
        },
        "outputs": {
            "summary": str(output_dir / "hot_update_gongfa_homemake_lifecycle_report.json"),
            "markdown": str(output_dir / "hot_update_gongfa_homemake_lifecycle_report.md"),
            "packets": str(output_dir / "hot_update_gongfa_homemake_lifecycle_packets.tsv"),
            "edges": str(output_dir / "hot_update_gongfa_homemake_lifecycle_edges.tsv"),
        },
    }
    (output_dir / "hot_update_gongfa_homemake_lifecycle_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def _collect_blld_keyword_rows(blld_dir: Path, categories: dict[str, list[str]]) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    for path in sorted(blld_dir.glob("*.lua"), key=lambda item: item.name.lower()):
        if "__" in path.stem:
            continue
        try:
            lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
        except OSError:
            continue
        for line_no, line in enumerate(lines, start=1):
            compact = line.strip()
            if not compact:
                continue
            lower = compact.lower()
            for category, terms in categories.items():
                for term in terms:
                    if term.lower() in lower:
                        rows.append(
                            {
                                "category": category,
                                "file": path.name,
                                "line": line_no,
                                "signal": term,
                                "text": compact,
                                "path": str(path),
                            }
                        )
                        break
    rows.sort(key=lambda item: (str(item["category"]), str(item["file"]), int(item["line"])))
    return rows


def _write_blld_finish_flow_markdown(
    path: Path,
    *,
    export_base: Path,
    blld_dir: Path,
    evidence_rows: list[dict[str, object]],
) -> None:
    by_category = Counter(str(row["category"]) for row in evidence_rows)

    def rows_for(category: str) -> list[dict[str, object]]:
        return [row for row in evidence_rows if row["category"] == category]

    lines = [
        "# BLLD 结算链路探针",
        "",
        f"- 导出目录：`{export_base}`",
        f"- BLLD Lua：`{blld_dir}`",
        f"- 证据行：{len(evidence_rows)}；分组：{', '.join(f'{name}:{count}' for name, count in by_category.most_common())}",
        "- 说明：本报告只描述客户端 Lua 的结算链路。服务端是否接受、校验或重算这些值，需要继续看服务端或实际抓包回包。",
        "",
        "## 结算链路",
        "",
        "1. `BLLDStartGame` 注册 `BLLDType.EventType.GameOver`，回调进入 `BLLDMgr:OnGameOver(isWin)`。",
        "2. 失败路径可见于玩家血量归零，触发 `GameOver,false`。",
        "3. 成功路径可见于撤离坚持时间结束，或撤离 boss 被击杀，触发 `GameOver,true`。",
        "4. `OnGameOver` 从 `InGameData:GetBagPlacementList()` 汇总 `rewardGroupId -> dropCount`，连同 `curLevelId/isWin` 发给 `CM_BlldFinishAndReward`。",
        "5. `CM_BlldFinishAndRewardFun` 同时带 `passRate`，失败时由 `Model:GetProgressVal()*100` 截断到 10000。",
        "6. 客户端最终展示依赖 `SM_BlldFinishAndReward` 回包落到 `Model:SetFinishAndReward(msg)`，成功后再 `CM_BlldSync`。",
        "",
    ]
    category_titles = [
        ("game_over", "GameOver 触发"),
        ("finish_send", "结算发送"),
        ("reward_find", "探索奖励"),
        ("progress", "进度与 passRate"),
        ("server_return", "服务端回包展示"),
    ]
    for category, title in category_titles:
        lines.extend([f"## {title}", "", "| 文件 | 行 | 信号 | 代码 |", "| --- | ---: | --- | --- |"])
        for row in rows_for(category)[:120]:
            lines.append(
                "| "
                f"{_markdown_table_cell(row.get('file', ''), limit=120)} | "
                f"{row.get('line', '')} | "
                f"{_markdown_table_cell(row.get('signal', ''), limit=120)} | "
                f"{_markdown_table_cell(row.get('text', ''), limit=260)} |"
            )
        lines.append("")
    path.write_text("\n".join(lines), encoding="utf-8")


def build_fanxiu_blld_finish_flow_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)
    blld_dir = _find_text_asset_dir(export_base, "lscripts", "gamesystem", "game", module="blld")
    if blld_dir is None:
        raise FanxiuResourceError("未找到已导出的 BLLD 游戏逻辑 TextAsset，请先运行热更新 lscripts 报告。")

    categories = {
        "game_over": [
            "EventType.GameOver",
            "RaiseEvent(BLLDType.EventType.GameOver",
            "OnGameOver",
            "BLLDStartGame",
        ],
        "finish_send": [
            "CM_BlldFinishAndRewardFun",
            "CM_BlldFinishAndReward.",
            "GetLevelId()",
            "GetBagPlacementList()",
        ],
        "reward_find": [
            "rewardFindInfo",
            "RewardFind",
            "rewardGroupId",
            "AutoPlaceBagItem",
            "GetBagPlacementList",
        ],
        "progress": [
            "PICKUP_ADD_PROGRESS",
            "LASTSURVIVE_PROGRESS",
            "AddProgressVal",
            "GetProgressVal",
            "passRate",
        ],
        "server_return": [
            "SM_BlldFinishAndReward",
            "SetFinishAndReward",
            "GetFinishAndReward",
            "FinishAndReward",
        ],
    }
    evidence_rows = _collect_blld_keyword_rows(blld_dir, categories)
    by_category = {category: [row for row in evidence_rows if row["category"] == category] for category in categories}

    evidence_count = _write_tsv(
        output_dir / "hot_update_blld_finish_flow_evidence.tsv",
        ["category", "file", "line", "signal", "text", "path"],
        evidence_rows,
    )
    summary_rows = [
        {
            "category": category,
            "evidence_count": len(rows),
            "files": _unique_join((row["file"] for row in rows), limit=30),
            "signals": _unique_join((row["signal"] for row in rows), limit=30),
        }
        for category, rows in by_category.items()
    ]
    summary_count = _write_tsv(
        output_dir / "hot_update_blld_finish_flow_summary.tsv",
        ["category", "evidence_count", "files", "signals"],
        summary_rows,
    )

    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "inputs": {"blld_dir": str(blld_dir)},
        "counts": {
            "evidence": evidence_count,
            "summary": summary_count,
            "by_category": dict(Counter(str(row["category"]) for row in evidence_rows).most_common()),
        },
        "outputs": {
            "summary": str(output_dir / "hot_update_blld_finish_flow_report.json"),
            "markdown": str(output_dir / "hot_update_blld_finish_flow_report.md"),
            "evidence": str(output_dir / "hot_update_blld_finish_flow_evidence.tsv"),
            "table": str(output_dir / "hot_update_blld_finish_flow_summary.tsv"),
        },
    }
    _write_blld_finish_flow_markdown(
        output_dir / "hot_update_blld_finish_flow_report.md",
        export_base=export_base,
        blld_dir=blld_dir,
        evidence_rows=evidence_rows,
    )
    (output_dir / "hot_update_blld_finish_flow_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def _find_cfg_text_asset_dir(export_base: Path, module: str) -> Path | None:
    return _find_text_asset_dir(export_base, "lscripts", "generate", "cfg", module=module)


def _parse_item_reward_token(token: object) -> tuple[int | None, int | None, str]:
    text = str(token or "")
    match = re.match(r"""(?i)item\|(\d+)(?:_(\d+))?""", text)
    if not match:
        return None, None, text
    item_id = int(match.group(1))
    count = int(match.group(2) or 1)
    return item_id, count, text


def _item_name(item_by_id: dict[int, dict[str, Any]], item_id: int | None) -> str:
    if item_id is None:
        return ""
    row = item_by_id.get(item_id, {})
    return _plain(row, "name") if row else ""


def _write_blld_reward_catalog_markdown(
    path: Path,
    *,
    export_base: Path,
    reward_group_rows: list[dict[str, object]],
    level_reward_rows: list[dict[str, object]],
) -> None:
    lines = [
        "# BLLD 奖励配置探针",
        "",
        f"- 导出目录：`{export_base}`",
        f"- 探索奖励组：{len(reward_group_rows)}；关卡奖励展开：{len(level_reward_rows)}",
        "- 说明：本报告还原客户端配置中的奖励展示和探索奖励池，不代表服务端最终发放结果。",
        "",
        "## 探索奖励组",
        "",
        "| 组 | 道具 | 名称 | 数量 | 限制 | 品质 | 权重 | 背包 |",
        "| ---: | ---: | --- | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in reward_group_rows:
        lines.append(
            "| "
            f"{row.get('reward_group_id', '')} | "
            f"{row.get('item_id', '')} | "
            f"{_markdown_table_cell(row.get('item_name', ''), limit=120)} | "
            f"{row.get('num', '')} | "
            f"{row.get('limit', '')} | "
            f"{row.get('quality', '')} | "
            f"{row.get('weight', '')} | "
            f"{row.get('bag', '')} |"
        )

    lines.extend(
        [
            "",
            "## 关卡探索奖励样例",
            "",
            "| 关卡 | 名称 | 奖励组 | 探索奖励 | 通关奖励标题 | 推送奖励样例 |",
            "| ---: | --- | --- | --- | --- | --- |",
        ]
    )
    level_rows = [row for row in level_reward_rows if row.get("reward_kind") == "find"]
    for row in level_rows[:80]:
        lines.append(
            "| "
            f"{row.get('level_id', '')} | "
            f"{_markdown_table_cell(row.get('level_name', ''), limit=100)} | "
            f"{row.get('reward_group_id', '')} | "
            f"{_markdown_table_cell(row.get('reward_text', ''), limit=180)} | "
            f"{_markdown_table_cell(row.get('reward_show_title', ''), limit=160)} | "
            f"{_markdown_table_cell(row.get('push_reward_preview', ''), limit=180)} |"
        )

    path.write_text("\n".join(lines), encoding="utf-8")


def build_fanxiu_blld_reward_catalog_probe(
    *,
    export_root: str | os.PathLike[str] | None = None,
) -> dict[str, Any]:
    export_base = resolve_fanxiu_export_root(export_root)
    output_dir = export_base / "apk_static_index"
    output_dir.mkdir(parents=True, exist_ok=True)
    lang_path = _find_lang_path(export_base)
    blld_dir = _find_cfg_text_asset_dir(export_base, "blld")
    item_dir = _find_cfg_text_asset_dir(export_base, "item")
    if blld_dir is None:
        raise FanxiuResourceError("未找到已导出的 BLLD 配置 TextAsset，请先运行热更新 lscripts 报告。")
    if item_dir is None:
        raise FanxiuResourceError("未找到已导出的 Item 配置 TextAsset，请先运行热更新 lscripts 报告。")

    reward_group = _parse_config(blld_dir / "RewardGroup.lua", lang_path)
    level = _parse_config(blld_dir / "Level.lua", lang_path)
    item = _parse_config(item_dir / "Item.lua", lang_path)
    item_by_id = _map_by_id(item["rows"])
    reward_group_by_id = _map_by_id(reward_group["rows"])

    reward_group_rows: list[dict[str, object]] = []
    for row in reward_group["rows"]:
        item_id = int(row.get("item") or 0)
        item_row = item_by_id.get(item_id, {})
        reward_group_rows.append(
            {
                "reward_group_id": row.get("id", ""),
                "item_id": item_id,
                "item_name": _item_name(item_by_id, item_id),
                "num": row.get("num", ""),
                "limit": row.get("limit", ""),
                "quality": row.get("quality", ""),
                "weight": row.get("weight", ""),
                "bag": row.get("bag", ""),
                "item_quality": item_row.get("quality", ""),
                "icon": item_row.get("icon", ""),
                "descript": _plain(item_row, "descript") if item_row else "",
            }
        )

    level_reward_rows: list[dict[str, object]] = []
    for row in level["rows"]:
        push_names: list[str] = []
        for token in row.get("pushReward") or []:
            item_id, count, raw = _parse_item_reward_token(token)
            name = _item_name(item_by_id, item_id)
            push_names.append(f"{name or raw}x{count or ''}".rstrip("x"))
        push_preview = " | ".join(push_names[:8])
        for group_token in row.get("findReward") or []:
            try:
                group_id = int(group_token)
            except (TypeError, ValueError):
                group_id = 0
            group_row = reward_group_by_id.get(group_id, {})
            item_id = int(group_row.get("item") or 0) if group_row else None
            item_name = _item_name(item_by_id, item_id)
            level_reward_rows.append(
                {
                    "level_id": row.get("id", ""),
                    "level_name": _plain(row, "name"),
                    "stage": row.get("stage", ""),
                    "layer": row.get("layer", ""),
                    "reward_kind": "find",
                    "reward_group_id": group_id,
                    "item_id": item_id or "",
                    "item_name": item_name,
                    "num": group_row.get("num", "") if group_row else "",
                    "limit": group_row.get("limit", "") if group_row else "",
                    "quality": group_row.get("quality", "") if group_row else "",
                    "weight": group_row.get("weight", "") if group_row else "",
                    "reward_text": f"{item_name or '未解析'} x{group_row.get('num', '')}" if group_row else f"未解析奖励组 {group_id}",
                    "reward_show_title": _plain(row, "rewardShowTitle"),
                    "push_reward_preview": push_preview,
                }
            )

    reward_group_count = _write_tsv(
        output_dir / "hot_update_blld_reward_groups.tsv",
        [
            "reward_group_id",
            "item_id",
            "item_name",
            "num",
            "limit",
            "quality",
            "weight",
            "bag",
            "item_quality",
            "icon",
            "descript",
        ],
        reward_group_rows,
    )
    level_reward_count = _write_tsv(
        output_dir / "hot_update_blld_level_rewards.tsv",
        [
            "level_id",
            "level_name",
            "stage",
            "layer",
            "reward_kind",
            "reward_group_id",
            "item_id",
            "item_name",
            "num",
            "limit",
            "quality",
            "weight",
            "reward_text",
            "reward_show_title",
            "push_reward_preview",
        ],
        level_reward_rows,
    )

    result = {
        "export_root": str(export_base),
        "output_dir": str(output_dir),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "inputs": {
            "lang_path": str(lang_path or ""),
            "blld_dir": str(blld_dir),
            "item_dir": str(item_dir),
        },
        "counts": {
            "reward_groups": reward_group_count,
            "level_rewards": level_reward_count,
            "levels": level["row_count"],
        },
        "outputs": {
            "summary": str(output_dir / "hot_update_blld_reward_catalog_report.json"),
            "markdown": str(output_dir / "hot_update_blld_reward_catalog_report.md"),
            "reward_groups": str(output_dir / "hot_update_blld_reward_groups.tsv"),
            "level_rewards": str(output_dir / "hot_update_blld_level_rewards.tsv"),
        },
    }
    _write_blld_reward_catalog_markdown(
        output_dir / "hot_update_blld_reward_catalog_report.md",
        export_base=export_base,
        reward_group_rows=reward_group_rows,
        level_reward_rows=level_reward_rows,
    )
    (output_dir / "hot_update_blld_reward_catalog_report.json").write_text(
        json.dumps(result, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return result


def _compact_json(value: object, *, limit: int = 220) -> str:
    if value in (None, "", [], {}):
        return ""
    if isinstance(value, (dict, list)):
        text = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    else:
        text = str(value)
    return text if len(text) <= limit else f"{text[:limit]}..."


def _numeric_values(rows: Iterable[dict[str, Any]], field: str) -> list[float]:
    values: list[float] = []
    for row in rows:
        try:
            values.append(float(row.get(field)))
        except (TypeError, ValueError):
            continue
    return values


def _range_text(values: Iterable[float]) -> str:
    items = list(values)
    if not items:
        return ""
    low = min(items)
    high = max(items)
    if low == high:
        return str(int(low)) if low.is_integer() else str(low)
    low_text = str(int(low)) if low.is_integer() else str(low)
    high_text = str(int(high)) if high.is_integer() else str(high)
    return f"{low_text}..{high_text}"


def _blld_effect_summary(effect_row: dict[str, Any]) -> str:
    fields = [
        "skill",
        "buffId",
        "targetBuffId",
        "extCd",
        "extDamage",
        "extReleaseCount",
        "criticalRate",
        "replaceSkill",
        "extDuration",
        "extBoomRange",
        "extSeekRange",
        "buffDamageRate",
        "addAttr",
    ]
    parts: list[str] = []
    for field in fields:
        value = effect_row.get(field)
        if value in (None, "", [], {}, 0):
            continue
        parts.append(f"{field}={_compact_json(value, limit=80)}")
    return "; ".join(parts)


